//! Operations that make or address a session.

use crate::escape_format;
use std::ffi::OsString;

use super::SESSION_FORMAT;
use super::{Effects, Op, Operation, Safety, Scope, SessionSlot, Slot};
use crate::Command;

/// Create a session.
///
/// # Examples
///
/// ```
/// use libtmux::plan::{NewSession, Plan};
///
/// let mut plan = Plan::new();
/// let session = plan.add(NewSession::new("work"));
/// // The session, its first window, and that window's pane all come from one
/// // command, so none of them costs a second round trip.
/// let _ = (session, session.window(), session.pane());
/// ```
#[derive(Clone, Debug)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[cfg_attr(feature = "serde", serde(deny_unknown_fields))]
#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
pub struct NewSession {
    #[cfg_attr(
        feature = "serde",
        serde(
            serialize_with = "crate::plan::wire::argument",
            deserialize_with = "crate::plan::wire::parse_argument"
        )
    )]
    #[cfg_attr(feature = "schema", schemars(with = "crate::plan::wire::Argument"))]
    name: OsString,
    #[cfg_attr(
        feature = "serde",
        serde(
            serialize_with = "crate::plan::wire::optional_argument",
            deserialize_with = "crate::plan::wire::parse_optional_argument"
        )
    )]
    #[cfg_attr(
        feature = "schema",
        schemars(with = "Option<crate::plan::wire::Argument>")
    )]
    start_directory: Option<OsString>,
    #[cfg_attr(
        feature = "serde",
        serde(
            serialize_with = "crate::plan::wire::optional_argument",
            deserialize_with = "crate::plan::wire::parse_optional_argument"
        )
    )]
    #[cfg_attr(
        feature = "schema",
        schemars(with = "Option<crate::plan::wire::Argument>")
    )]
    window_name: Option<OsString>,
}

impl NewSession {
    /// Create a detached session with this name.
    #[must_use]
    pub fn new(name: impl Into<OsString>) -> Self {
        Self {
            name: name.into(),
            start_directory: None,
            window_name: None,
        }
    }

    /// Start the session's first window in this directory.
    ///
    /// tmux expands this as a format, so [`crate::escape_format`] belongs
    /// around text a program did not write.
    #[must_use]
    pub fn start_directory(mut self, directory: impl Into<OsString>) -> Self {
        self.start_directory = Some(directory.into());
        self
    }

    /// Name the session's first window.
    #[must_use]
    pub fn window_name(mut self, name: impl Into<OsString>) -> Self {
        self.window_name = Some(name.into());
        self
    }

    pub(crate) fn render(&self) -> Command {
        let mut command = Command::new("new-session")
            .arg("-d")
            .arg("-P")
            .arg("-F")
            .arg(SESSION_FORMAT)
            .arg("-s")
            .arg(escape_format(&self.name));
        if let Some(directory) = &self.start_directory {
            command = command.arg("-c").arg(escape_format(directory));
        }
        if let Some(name) = &self.window_name {
            command = command.arg("-n").arg(escape_format(name));
        }
        command
    }
}

operation!(
    NewSession,
    creates = Slot<SessionSlot>,
    effects = Effects {
        creates: Some(Scope::Session),
        ..Effects::MUTATING
    },
    safety = Safety::Mutating
);

crates/libtmux/src/plan/ops/timing.rs.content:
//! Operations about when the next one runs rather than about an object.

use std::time::Duration;

use crate::Command;

use super::{Chainable, Effects, Op, Operation, Safety};

/// Wait before the next operation runs.
///
/// Renders `run-shell -d SECONDS` with no command, which every supported tmux
/// accepts: the client waits out the delay and runs nothing. The wait happens
/// in tmux, so a pause folded into a shared invocation still falls between
/// its neighbours, and a plan pauses in the same place whatever its
/// [`Planner`](crate::plan::Planner).
///
/// A shell does not need one to catch typed input: tmux holds it until the
/// pane reads it. A pause is for a program that drops what arrives before it
/// is ready.
///
/// A control-mode connection cannot carry one, because tmux answers a delayed
/// `run-shell` there at once and holds the next command instead:
/// [`Plan::run_over_control_mode`](crate::plan::Plan::run_over_control_mode),
/// and [`Plan::run`](crate::plan::Plan::run) on a handle from
/// `Server::over_control_mode`, refuse a plan holding a pause with
/// `ControlModeErrorKind::BlockingCommand` before sending anything.
///
/// # Examples
///
/// ```
/// # fn main() -> Result<(), Box<dyn std::error::Error>> {
/// use std::time::Duration;
///
/// use libtmux::PaneId;
/// use libtmux::plan::{Pause, Plan, SendKeys};
///
/// let pane: PaneId = "%1".parse()?;
/// let mut plan = Plan::new();
/// plan.add(SendKeys::new(pane.clone()).text("./start-db").enter());
/// plan.add(Pause::new(Duration::from_millis(1500)));
/// plan.add(SendKeys::new(pane).text("./migrate").enter());
///
/// let pause = plan.preview().remove(1).ok_or("a pause renders")?;
/// assert_eq!(pause.summary().to_string(), r#""run-shell" "-d" "1.5""#);
/// # Ok(())
/// # }
/// ```
#[derive(Clone, Debug)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[cfg_attr(feature = "serde", serde(deny_unknown_fields))]
#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
pub struct Pause {
    #[cfg_attr(
        feature = "serde",
        serde(
            rename = "seconds",
            serialize_with = "crate::plan::wire::seconds",
            deserialize_with = "crate::plan::wire::parse_seconds"
        )
    )]
    #[cfg_attr(feature = "schema", schemars(rename = "seconds", with = "f64"))]
    duration: Duration,
}

impl Pause {
    /// Wait `duration` before the next operation.
    #[must_use]
    pub const fn new(duration: Duration) -> Self {
        Self { duration }
    }

    /// How long this operation waits.
    #[must_use]
    pub const fn duration(&self) -> Duration {
        self.duration
    }

    pub(crate) fn render(&self) -> Command {
        // tmux reads the delay with `strtod`, and `f64`'s `Display` never
        // writes an exponent, so any `Duration` arrives as plain seconds.
        Command::new("run-shell")
            .arg("-d")
            .arg(self.duration.as_secs_f64().to_string())
    }
}

operation!(
    Pause,
    creates = (),
    effects = Effects {
        read_only: true,
        idempotent: true,
        ..Effects::MUTATING
    },
    safety = Safety::ReadOnly,
    chainable
);

crates/libtmux/src/plan/ops/windows.rs.content:
//! Operations that make or address a window.

use crate::escape_format;
use std::ffi::OsString;
use std::fmt;

use super::{
    Chainable, Effects, Op, Operation, Safety, Scope, SessionTarget, Slot, WindowSlot, WindowTarget,
};
use super::{Resolver, WINDOW_FORMAT};
use crate::Command;
use crate::window::assignment;

/// Create a window in a session.
#[derive(Clone)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[cfg_attr(feature = "serde", serde(deny_unknown_fields))]
#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
pub struct NewWindow {
    pub(crate) target: SessionTarget,
    #[cfg_attr(
        feature = "serde",
        serde(
            serialize_with = "crate::plan::wire::optional_argument",
            deserialize_with = "crate::plan::wire::parse_optional_argument"
        )
    )]
    #[cfg_attr(
        feature = "schema",
        schemars(with = "Option<crate::plan::wire::Argument>")
    )]
    name: Option<OsString>,
    #[cfg_attr(
        feature = "serde",
        serde(
            serialize_with = "crate::plan::wire::optional_argument",
            deserialize_with = "crate::plan::wire::parse_optional_argument"
        )
    )]
    #[cfg_attr(
        feature = "schema",
        schemars(with = "Option<crate::plan::wire::Argument>")
    )]
    start_directory: Option<OsString>,
    #[cfg_attr(
        feature = "serde",
        serde(
            serialize_with = "crate::plan::wire::optional_argument",
            deserialize_with = "crate::plan::wire::parse_optional_argument"
        )
    )]
    #[cfg_attr(
        feature = "schema",
        schemars(with = "Option<crate::plan::wire::Argument>")
    )]
    command: Option<OsString>,
    #[cfg_attr(
        feature = "serde",
        serde(
            serialize_with = "crate::plan::wire::pairs",
            deserialize_with = "crate::plan::wire::parse_pairs"
        )
    )]
    #[cfg_attr(
        feature = "schema",
        schemars(with = "Vec<(crate::plan::wire::Argument, crate::plan::wire::Argument)>")
    )]
    environment: Vec<(OsString, OsString)>,
    index: Option<u32>,
    focus: bool,
}

impl NewWindow {
    /// Create a detached window in this session.
    #[must_use]
    pub fn new(target: impl Into<SessionTarget>) -> Self {
        Self {
            target: target.into(),
            name: None,
            start_directory: None,
            command: None,
            environment: Vec::new(),
            index: None,
            focus: false,
        }
    }

    /// Place the window at this index rather than the next free one.
    #[must_use]
    pub const fn index(mut self, index: u32) -> Self {
        self.index = Some(index);
        self
    }

    /// Set a variable in the window's environment before it starts.
    #[must_use]
    pub fn environment(mut self, name: impl Into<OsString>, value: impl Into<OsString>) -> Self {
        self.environment.push((name.into(), value.into()));
        self
    }

    /// Leave the new window, and so its pane, active.
    ///
    /// A focused creation is what makes the `{marked}` fold available: the
    /// register the fold marks is the active pane.
    #[must_use]
    pub const fn focus(mut self) -> Self {
        self.focus = true;
        self
    }

    pub(crate) const fn focuses(&self) -> bool {
        self.focus
    }

    /// Name the window.
    ///
    /// tmux expands this as a format, so [`crate::escape_format`] belongs
    /// around text a program did not write.
    #[must_use]
    pub fn name(mut self, name: impl Into<OsString>) -> Self {
        self.name = Some(name.into());
        self
    }

    /// Start the window's pane in this directory.
    ///
    /// tmux expands this as a format, so [`crate::escape_format`] belongs
    /// around text a program did not write.
    #[must_use]
    pub fn start_directory(mut self, directory: impl Into<OsString>) -> Self {
        self.start_directory = Some(directory.into());
        self
    }

    /// Run this instead of a shell in the window's pane.
    #[must_use]
    pub fn command(mut self, command: impl Into<OsString>) -> Self {
        self.command = Some(command.into());
        self
    }

    pub(crate) fn render(&self, resolve: Resolver<'_>) -> Option<Command> {
        // tmux takes the session, not the session's current window, when the
        // target ends in a colon; an index after it asks for that slot.
        let mut token = self.target.token(resolve)?;
        token.push(":");
        if let Some(index) = self.index {
            token.push(index.to_string());
        }
        let mut command = Command::new("new-window")
            .arg("-P")
            .arg("-F")
            .arg(WINDOW_FORMAT)
            .arg("-t")
            .arg(token);
        if !self.focus {
            command = command.arg("-d");
        }
        if let Some(name) = &self.name {
            command = command.arg("-n").arg(escape_format(name));
        }
        if let Some(directory) = &self.start_directory {
            command = command.arg("-c").arg(escape_format(directory));
        }
        for (name, value) in &self.environment {
            command = command.arg("-e").sensitive_arg(assignment(name, value));
        }
        // The shell command is positional, so it goes last: tmux stops parsing
        // flags at the first one.
        if let Some(shell_command) = &self.command {
            command = command.arg("--").sensitive_arg(shell_command.clone());
        }
        Some(command)
    }
}

impl fmt::Debug for NewWindow {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("NewWindow")
            .field("target", &self.target)
            .field("has_name", &self.name.is_some())
            .field("has_start_directory", &self.start_directory.is_some())
            .field("has_command", &self.command.is_some())
            .field("environment_count", &self.environment.len())
            .field("index", &self.index)
            .field("focus", &self.focus)
            .finish()
    }
}

