use std::ffi::{OsStr, OsString};

use super::{Chooser, Server};
use crate::client::Client;
use crate::internal::listing;
use crate::{Command, Error};

impl Server {
    /// Show a popup over a client, running a command inside it.
    ///
    /// This needs a client with a terminal, so it fails on a server nothing is
    /// attached to.
    ///
    /// Unlike [`Self::command_prompt`] and [`Self::display_menu`], this does
    /// not wait for a person -- but it does wait for the command. The popup is
    /// opened with `-E`, so it closes when what runs inside it exits, and this
    /// returns then. A command that does not end holds the call until the
    /// dispatch timeout does.
    ///
    /// # Errors
    ///
    /// Returns [`Error::ServerMismatch`] when the client belongs to another
    /// server, or an error when no suitable client exists, when tmux refuses
    /// the command, and when the dispatch timeout expires before it exits.
    pub async fn display_popup(
        &self,
        client: Option<&Client>,
        command: impl Into<OsString>,
    ) -> Result<(), Error> {
        let mut popup = Command::new("display-popup").arg("-E");
        if let Some(client) = client {
            self.core
                .require_same_server(client.server_identity(), "display-popup")?;
            popup = popup
                .arg("-t")
                .arg(client.name().to_string_lossy().into_owned());
        }

        listing::mutate(&self.core, "display-popup", popup.arg(command.into())).await
    }

    /// Show a menu over a client.
    ///
    /// Items appear in the order given. This needs a client with a terminal.
    ///
    /// Like [`Self::command_prompt`], this waits for the person: tmux holds the
    /// invocation until an item is chosen or the menu is dismissed, and the
    /// dispatch timeout is what ends the wait when nobody does.
    ///
    /// # Errors
    ///
    /// Returns [`Error::ServerMismatch`] when the client belongs to another
    /// server, or an error when no suitable client exists, when tmux refuses
    /// an item, and when the dispatch timeout expires before anyone chooses.
    pub async fn display_menu(
        &self,
        client: Option<&Client>,
        title: &str,
        items: impl IntoIterator<Item = MenuItem>,
    ) -> Result<(), Error> {
        let mut menu = Command::new("display-menu")
            .arg("-T")
            .arg(OsString::from(title));
        if let Some(client) = client {
            self.core
                .require_same_server(client.server_identity(), "display-menu")?;
            menu = menu
                .arg("-t")
                .arg(client.name().to_string_lossy().into_owned());
        }
        for item in items {
            menu = menu.arg(item.label).arg(item.key).arg(item.command);
        }

        listing::mutate(&self.core, "display-menu", menu).await
    }

    /// Open a command prompt on a client.
    ///
    /// The prompt runs `command` once the user answers, with `%%` replaced by
    /// what they typed.
    ///
    /// This does not return when the prompt opens. tmux holds the invocation
    /// until somebody answers or dismisses it, so a caller is waiting on a
    /// person -- and on a server nobody is watching, on nobody. The dispatch
    /// timeout is what ends that wait: with the default it fails after thirty
    /// seconds having opened a prompt that is still there. Give the call a
    /// server whose `default_timeout` suits a human, or drive it from a task
    /// that may take that long.
    ///
    /// Passing a client is not what decides this. Both forms wait; naming one
    /// only decides which terminal the prompt appears on.
    ///
    /// # Errors
    ///
    /// Returns [`Error::ServerMismatch`] when the client belongs to another
    /// server, or an error when no suitable client exists, when tmux refuses,
    /// and when the dispatch timeout expires before the prompt is answered.
    pub async fn command_prompt(
        &self,
        client: Option<&Client>,
        prompt: Option<&str>,
        command: impl Into<OsString>,
    ) -> Result<(), Error> {
        let mut request = Command::new("command-prompt");
        if let Some(client) = client {
            self.core
                .require_same_server(client.server_identity(), "command-prompt")?;
            request = request
                .arg("-t")
                .arg(client.name().to_string_lossy().into_owned());
        }
        if let Some(prompt) = prompt {
            request = request.arg("-p").arg(OsString::from(prompt));
        }

        listing::mutate(&self.core, "command-prompt", request.arg(command.into())).await
    }

    /// Open one of tmux's interactive choosers on a client.
    ///
    /// A chooser opens *in a pane*, which is why this needs no client and
    /// succeeds on a server nothing is attached to: the pane's `pane_in_mode`
    /// becomes `1` and its `pane_mode` becomes `tree-mode`, client or not.
    ///
    /// That is the difference from [`Self::display_popup`],
    /// [`Self::display_menu`], [`Self::command_prompt`] and
    /// [`Self::display_panes`], which draw *on a client* and report "no current
    /// client" without one. Passing `client` here only says which client's
    /// current pane to open in.
    ///
    /// # Errors
    ///
    /// Returns [`Error::ServerMismatch`] when the client belongs to another
    /// server, or an error when tmux refuses the command. A missing client is
    /// not one: this does not need one.
    pub async fn choose(&self, chooser: Chooser, client: Option<&Client>) -> Result<(), Error> {
        let name = chooser.command();
        let mut request = Command::new(name);
        if let Some(client) = client {
            self.core
                .require_same_server(client.server_identity(), name)?;
            request = request
                .arg("-t")
                .arg(client.name().to_string_lossy().into_owned());
        }

        listing::mutate(&self.core, name, request).await
    }

    /// Open tmux's window finder for a search string.
    ///
    /// This is separate from [`Server::choose`] because it needs something to
    /// search for, where the other choosers list what already exists. Like them
    /// it opens in a pane rather than on a client, so it needs no client and
    /// leaves the pane in `tree-mode` on a server nothing is attached to.
    ///
    /// # Errors
    ///
    /// Returns [`Error::ServerMismatch`] when the client belongs to another
    /// server, or an error when tmux refuses the command. A missing client is
    /// not one: this does not need one.
    pub async fn find_window(&self, client: Option<&Client>, search: &str) -> Result<(), Error> {
        let mut request = Command::new("find-window");
        if let Some(client) = client {
            self.core
                .require_same_server(client.server_identity(), "find-window")?;
            request = request
                .arg("-t")
                .arg(client.name().to_string_lossy().into_owned());
        }

        listing::mutate(
            &self.core,
            "find-window",
            request.arg(OsString::from(search)),
        )
        .await
    }

    /// Briefly show each pane's number on a client.
    ///
    /// From tmux 3.8, `display-panes` is a pane mode rather than an overlay
    /// on the client: tmux accepts it with no client attached and shows the
    /// numbers in the target pane until `display-panes-time` passes or a key
    /// is pressed.
    ///
    /// # Errors
    ///
    /// Returns [`Error::ServerMismatch`] when the client belongs to another
    /// server, or an error when tmux refuses, including below 3.8 when no
    /// suitable client exists.
    pub async fn display_panes(&self, client: Option<&Client>) -> Result<(), Error> {
        let mut request = Command::new("display-panes");
        if let Some(client) = client {
            self.core
                .require_same_server(client.server_identity(), "display-panes")?;
            request = request
                .arg("-t")
                .arg(client.name().to_string_lossy().into_owned());
        }

        listing::mutate(&self.core, "display-panes", request).await
    }
}

/// One line of a [`Server::display_menu`] menu.
///
/// The three parts were a `(String, String, String)` triple, which reads the
/// same whichever order they are in and compiles whichever order they are in.
///
/// # Examples
///
/// ```no_run
/// # async fn menu(server: &libtmux::Server) -> Result<(), libtmux::Error> {
/// use libtmux::MenuItem;
///
/// server
///     .display_menu(
///         None,
///         "session",
///         [
///             MenuItem::new("Detach", "d", "detach-client"),
///             MenuItem::new("Kill", "k", "kill-session"),
///         ],
///     )
///     .await?;
/// # Ok(())
/// # }
/// ```
#[derive(Clone, Debug, Eq, Hash, PartialEq)]
pub struct MenuItem {
    label: OsString,
    key: OsString,
    command: OsString,
}

impl MenuItem {
    /// Show `label`, and run `command` when the person presses `key`.
    ///
    /// `key` is a tmux key name, or `-` for a line that cannot be chosen.
    ///
    /// # Examples
    ///
    /// ```
    /// use libtmux::MenuItem;
    ///
    /// let item = MenuItem::new("Kill the session", "k", "kill-session");
    /// assert_eq!(item.label(), "Kill the session");
    /// ```
    #[must_use]
    pub fn new(
        label: impl Into<OsString>,
        key: impl Into<OsString>,
        command: impl Into<OsString>,
    ) -> Self {
        Self {
            label: label.into(),
            key: key.into(),
            command: command.into(),
        }
    }

    /// The text tmux shows.
    #[must_use]
    pub fn label(&self) -> &OsStr {
        &self.label
    }

    /// The key that chooses this line.
    #[must_use]
    pub fn key(&self) -> &OsStr {
        &self.key
    }

    /// The tmux command this line runs.
    #[must_use]
    pub fn command(&self) -> &OsStr {
        &self.command
    }
}

crates/libtmux/src/server/keys.rs.content:
//! Key bindings read as fields through `list-keys -F`.

use super::Server;
use crate::formats::{
    FormatCodecError, FormatCodecErrorKind, FormatCodecPhase, TmuxText, TransportDialect,
};
use crate::version::since::LIST_KEYS_FORMAT;
use crate::{Command, Error, ListingDecodeError};

/// The fields [`TEMPLATE`] renders, in order.
const FIELDS: [&str; 5] = [
    "key_table",
    "key_string",
    "key_repeat",
    "key_note",
    "key_command",
];

/// `list-keys -F` template for [`FIELDS`], framed as a format plan's is.
const TEMPLATE: &str =
    "#{q:key_table}=#{q:key_string}=#{key_repeat}=#{q:key_note}=#{q:key_command}=";

/// One key binding, as tmux holds it.
///
/// `bind-key -n` is `-T root`, so [`Self::table`] answers it. The command is
/// the text a `bind-key` line in a configuration file carries, with `\;`
/// between commands, and is not parsed further. That is argument syntax: as
/// the single command string [`Server::bind_key`] takes, `\;` is a literal
/// semicolon rather than a separator.
///
/// # Examples
///
/// ```
/// # fn main() -> Result<(), Box<dyn std::error::Error>> {
/// # let runtime = tokio::runtime::Builder::new_current_thread().enable_all().build()?;
/// # runtime.block_on(async {
/// let guard = libtmux::test::TestServer::new().await?;
/// let server = guard.server();
/// server.bind_key("prefix", "Y", "display-message hello").await?;
///
/// let version = server.capabilities().await?.tmux_version().clone();
/// if version.has_behavior(&libtmux::since::LIST_KEYS_FORMAT) {
///     let bindings = server.typed_key_bindings(Some("prefix")).await?;
///     let bound = bindings
///         .iter()
///         .find(|binding| binding.key() == "Y")
///         .ok_or("the binding is listed")?;
///     assert_eq!(bound.command(), "display-message hello");
///     assert!(!bound.repeats());
///     assert_eq!(bound.note(), None);
/// }
///
/// guard.shutdown().await?;
/// # Ok::<(), Box<dyn std::error::Error>>(())
/// # })?;
/// # Ok(())
/// # }
/// ```
#[derive(Clone, Debug, Eq, Hash, PartialEq)]
pub struct KeyBinding {
    table: TmuxText,
    key: TmuxText,
    command: TmuxText,
    note: Option<TmuxText>,
    repeats: bool,
}

impl KeyBinding {
    /// Return the key table, such as `prefix`, `root` or `copy-mode-vi`.
    #[must_use]
    pub const fn table(&self) -> &TmuxText {
        &self.table
    }

    /// Return the key as tmux names it, such as `C-b` or `"`, unquoted.
    #[must_use]
    pub const fn key(&self) -> &TmuxText {
        &self.key
    }

    /// Return the bound command list, as a `bind-key` line renders it.
    #[must_use]
    pub const fn command(&self) -> &TmuxText {
        &self.command
    }

    /// Return the note `bind-key -N` attached, if any.
    ///
    /// An empty note reads as none: tmux reports both as an empty value.
    #[must_use]
    pub const fn note(&self) -> Option<&TmuxText> {
        self.note.as_ref()
    }

    /// Report whether the binding repeats, `bind-key -r`.
    #[must_use]
    pub const fn repeats(&self) -> bool {
        self.repeats
    }
}

/// Decode `list-keys -F` output rendered with [`TEMPLATE`].
///
/// A row that does not frame, or whose repeat flag is neither `0` nor `1`,
/// fails the whole listing rather than being skipped.
fn parse(stdout: &[u8]) -> Result<Vec<KeyBinding>, FormatCodecError> {
    // `list-keys -F` arrived in 3.7, after the `vis` releases.
    crate::formats::split_quoted_rows(stdout, FIELDS, TransportDialect::RawQ)?
        .into_iter()
        .enumerate()
        .map(|(row, [table, key, repeat, note, command])| {
            let repeats = match repeat.as_slice() {
                b"0" => false,
                b"1" => true,
                _ => {
                    return Err(FormatCodecError::uncatalogued(
                        FormatCodecErrorKind::InvalidValue,
                        FormatCodecPhase::Decode,
                        row,
                        2,
                        FIELDS[2],
                        None,
                    ));
                }
            };
            Ok(KeyBinding {
                table: TmuxText::from(table),
                key: TmuxText::from(key),
                command: TmuxText::from(command),
                note: (!note.is_empty()).then(|| TmuxText::from(note)),
                repeats,
            })
        })
        .collect()
}

impl Server {
    /// List key bindings as fields: table, key, command, note and repeat.
    ///
    /// `table` narrows the listing to one key table. A table with no bindings
    /// lists empty, since tmux keeps no empty table to refuse.
    ///
    /// Every table is fetched and the narrowing done here. tmux 3.7 through
    /// 3.7c send a listing of exactly one binding to the message log instead
    /// of printing it, so `list-keys -T` on a table holding one binding
    /// answers with nothing. Across every table, that happens only on a
    /// server with a single binding left, which lists none on those releases.
    ///
    /// # Errors
    ///
    /// Returns [`Error::UnsupportedCapability`] below tmux 3.7, which has no
    /// `list-keys -F`; [`Self::key_bindings`] reads the `bind-key` lines
    /// those releases print. Returns [`Error::DecodeListing`] when a row does
    /// not decode, and an error when tmux cannot be reached or refuses the
    /// listing.
    pub async fn typed_key_bindings(&self, table: Option<&str>) -> Result<Vec<KeyBinding>, Error> {
        self.require("list-keys formats", LIST_KEYS_FORMAT).await?;

        let result = self
            .cmd(Command::new("list-keys").arg("-F").arg(TEMPLATE))
            .await?;
        if !result.success() {
            return Err(Error::from_refused_result("list-keys", &result, None));
        }

        let bindings = parse(result.stdout()).map_err(|detail| Error::DecodeListing {
            list_command: "list-keys",
            detail: ListingDecodeError::new(detail),
        })?;
        Ok(match table {
            Some(table) => bindings
                .into_iter()
                .filter(|binding| binding.table == table)
                .collect(),
            None => bindings,
        })
    }
}

/// Decode `list-keys -F` output, for fuzzing only.
///
/// Not a supported API: it lets a fuzzer reach the decoder without making it
/// public, behind a feature no release turns on.
#[cfg(feature = "unstable-fuzzing")]
#[doc(hidden)]
pub fn __fuzz_parse_key_bindings(stdout: &[u8]) {
    let _ = parse(stdout);
}

#[cfg(test)]
mod tests {
    use super::{KeyBinding, parse};
    use crate::TmuxText;
    use crate::formats::FormatCodecErrorKind;

    fn binding(table: &str, key: &str, command: &str) -> KeyBinding {
        KeyBinding {
            table: TmuxText::from(table),
            key: TmuxText::from(key),
            command: TmuxText::from(command),
            note: None,
            repeats: false,
        }
    }

    /// tmux 3.7c's output for two bindings; its `#{q:}` leaves LF bare.
    #[test]
    fn rows_decode_escapes_and_keep_bare_newlines() {
        let stdout = br#"solo=M-\'=0==display-message\ a\=b\ \\\;\ display-message\ c=
sp\ ace=\"=1=a
note=display-message\ \"two\ words\"=
"#;

        let solo = binding("solo", "M-'", r"display-message a=b \; display-message c");
        let mut spaced = binding("sp ace", "\"", "display-message \"two words\"");
        spaced.note = Some(TmuxText::from("a\nnote"));
        spaced.repeats = true;

        assert_eq!(parse(stdout), Ok(vec![solo, spaced]));
        assert_eq!(parse(b""), Ok(Vec::new()));
    }

    /// Each malformed shape fails the listing; none yields a shorter one.
    #[test]
    fn a_row_that_does_not_frame_fails_the_listing() {
        let good = b"root=x=0==send-keys=\n".as_slice();
        for (stdout, kind) in [
            (
                b"root=x=0==send-keys".as_slice(),
                FormatCodecErrorKind::MissingFieldTerminator,
            ),
            (b"root=x=0==send-keys=", FormatCodecErrorKind::MissingRowLf),
            (
                b"root=x=0==send-keys=x\n",
                FormatCodecErrorKind::UnexpectedRowTerminator,
            ),
            (
                b"root=\\x=0==send-keys=\n",
                FormatCodecErrorKind::InvalidEscape,
            ),
            (b"root=x\\", FormatCodecErrorKind::DanglingEscape),
            (
                b"root=x\0=0==send-keys=\n",
                FormatCodecErrorKind::EmbeddedNul,
            ),
            (
                b"root=x=2==send-keys=\n",
                FormatCodecErrorKind::InvalidValue,
            ),
        ] {
            let listing = [good, stdout].concat();
            let error = parse(&listing).expect_err("a malformed row fails");
            assert_eq!(error.kind(), kind, "{:?}", String::from_utf8_lossy(stdout));
            assert_eq!(error.row(), Some(1));
        }
    }
}

crates/libtmux/src/server/settings.rs.content:
use std::collections::BTreeMap;
use std::ffi::OsString;

use super::Server;
use crate::formats::TmuxText;
use crate::internal::{environment, options};
use crate::{EnvironmentEntry, Error, IndexedHooks, OptionValue, ReplaceMode, SparseValues};

/// The table tmux keeps an array option in, reached from a `Server` handle.
///
/// tmux's eight array options span three tables: `command-alias` and the
/// terminal ones are server options, `status-format` and `update-environment`
/// session ones, and `pane-colours` belongs to a window and a pane both. This
/// handle offers one family of methods for all of them, so the name has to
/// pick the table. Sending one scope for every name reached the right table
/// only because tmux resolves an option by its name and ignored the flag.
///
/// For an option that is not the server's, the global table is the
/// server-wide default this handle can address; a particular session's or
/// window's copy is reached through that object's own handle.
fn array_scope(name: &str) -> options::Scope<'static> {
    match crate::option_schema(name).map(crate::OptionSchema::scopes) {
        Some(scopes) if scopes.contains(&crate::OptionScope::Server) => options::Scope::Server,
        Some(scopes) if scopes.contains(&crate::OptionScope::Window) => {
            options::Scope::GlobalWindow
        }
        _ => options::Scope::GlobalSession,
    }
}

impl Server {
    /// List the server option names.
    ///
    /// Values are not included: tmux renders them for display with three
    /// different quoting styles, so re-parsing them would be guesswork. Read
    /// each value with [`Self::typed_option`], which decodes the exact bytes.
    ///
    /// Names are `String`, not [`TmuxText`](crate::TmuxText), because tmux's
    /// own are ASCII and every option method takes one as `&str`; a user
    /// option (`@name`) lists cut at any whitespace in its name, and with
    /// U+FFFD for bytes that are not UTF-8, since `show-options` prints names
    /// unframed.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux refuses the listing.
    pub async fn option_names(&self) -> Result<Vec<String>, Error> {
        options::names(&self.core, options::Scope::Server).await
    }

    /// Read every option set at this server, decoded by its declared kind.
    ///
    /// Costs one tmux command per option, because each value is read as the
    /// bytes tmux stored rather than the form it lists them in. Use
    /// [`Self::option_names`] when only the names are wanted, and
    /// [`Self::typed_option`] for one value.
    ///
    /// An array option keeps the indexed name tmux lists it under, so
    /// `command-alias[0]` and `command-alias[1]` are separate entries.
    ///
    /// Reports what is set *at this scope*, not what the object resolves to.
    /// A session that has set nothing of its own answers empty even though
    /// every option still has an effective value it inherits.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux cannot be reached or refuses the listing.
    /// An empty map means nothing is set, never that the listing failed.
    ///
    /// # Examples
    ///
    /// ```
    /// # fn main() -> Result<(), Box<dyn std::error::Error>> {
    /// # let runtime = tokio::runtime::Builder::new_current_thread().enable_all().build()?;
    /// # runtime.block_on(async {
    /// let guard = libtmux::test::TestServer::new().await?;
    /// let server = guard.server();
    ///
    /// server.set_option("buffer-limit", "42").await?;
    /// let options = server.options().await?;
    /// assert!(options.contains_key("buffer-limit"));
    ///
    /// guard.shutdown().await?;
    /// # Ok::<(), Box<dyn std::error::Error>>(())
    /// # })?;
    /// # Ok(())
    /// # }
    /// ```
    pub async fn options(&self) -> Result<BTreeMap<String, OptionValue>, Error> {
        options::typed_all(&self.core, options::Scope::Server).await
    }

    /// Set one server option to text, unchecked.
    ///
    /// tmux validates the value itself. [`Self::set_typed_option`] checks it
    /// against tmux's option table first; [`OptionValue`] compares the two.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux rejects the name or value.
    pub async fn set_option(&self, name: &str, value: impl Into<OsString>) -> Result<(), Error> {
        options::set(&self.core, options::Scope::Server, name, value, false).await
    }

    /// Set one server option to a typed value, checked before it is sent.
    ///
    /// The value must be the variant [`Self::typed_option`] reads back for
    /// the option; [`OptionValue`] gives the rules, and what is not checked.
    ///
    /// # Errors
    ///
    /// Returns [`Error::OptionValueRefused`] without sending anything when
    /// tmux's option table refuses the value, and
    /// [`Error::OptionScopeMismatch`] when the option is not a server option.
    /// Otherwise returns an error when tmux rejects the name or value.
    ///
    /// # Examples
    ///
    /// ```no_run
    /// # async fn example(server: &libtmux::Server) -> Result<(), libtmux::Error> {
    /// server.set_typed_option("escape-time", 10).await?;
    /// # Ok(())
    /// # }
    /// ```
    pub async fn set_typed_option(
        &self,
        name: &str,
        value: impl Into<OptionValue>,
    ) -> Result<(), Error> {
        options::set_typed(&self.core, options::Scope::Server, name, value.into()).await
    }

    /// Remove one server option.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux rejects the name.
    pub async fn unset_option(&self, name: &str) -> Result<(), Error> {
        options::unset(&self.core, options::Scope::Server, name).await
    }

    /// Set one global session option to text, unchecked.
    ///
    /// Sessions inherit from this table, so it is where a default belongs.
    /// [`Self::set_typed_global_option`] checks the value first.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux rejects the name or value.
    pub async fn set_global_option(
        &self,
        name: &str,
        value: impl Into<OsString>,
    ) -> Result<(), Error> {
        options::set(
            &self.core,
            options::Scope::GlobalSession,
            name,
            value,
            false,
        )
        .await
    }

    /// Set one global session option to a typed value, checked before it is
    /// sent.
    ///
    /// The value must be the variant [`Self::typed_global_option`] reads back
    /// for the option; [`OptionValue`] gives the rules, and what is not
    /// checked.
    ///
    /// # Errors
    ///
    /// Returns [`Error::OptionValueRefused`] without sending anything when
    /// tmux's option table refuses the value, and
    /// [`Error::OptionScopeMismatch`] when the option is not a session option.
    /// Otherwise returns an error when tmux rejects the name or value.
    ///
    /// # Examples
    ///
    /// ```no_run
    /// # async fn example(server: &libtmux::Server) -> Result<(), libtmux::Error> {
    /// server.set_typed_global_option("mouse", true).await?;
    /// server.set_typed_global_option("history-limit", 50_000).await?;
    /// server.set_typed_global_option("status-position", "top").await?;
    /// # Ok(())
    /// # }
    /// ```
    pub async fn set_typed_global_option(
        &self,
        name: &str,
        value: impl Into<OptionValue>,
    ) -> Result<(), Error> {
        options::set_typed(
            &self.core,
            options::Scope::GlobalSession,
            name,
            value.into(),
        )
        .await
    }

    /// Set a variable in the server's own environment.
    ///
    /// tmux keeps this and each session's environment in separate stores, and
    /// merges them only when it starts a process. So a name set here is
    /// reported as an unknown variable by
    /// [`Session::environment`](crate::Session::environment) -- reading
    /// a session does not fall back to the server -- while a pane started
    /// afterwards is handed it all the same.
    ///
    /// Where both hold a name, the session's value is the one the process
    /// gets. [`Self::hide_environment`] removes the name from the merge
    /// entirely.
    ///
    /// Panes already running keep the environment they were started with.
    ///
    /// The value is marked sensitive, since an environment carries tokens.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux rejects the name or value.
    ///
    /// # Examples
    ///
    /// ```
    /// # fn main() -> Result<(), Box<dyn std::error::Error>> {
    /// # let runtime = tokio::runtime::Builder::new_current_thread().enable_all().build()?;
    /// # runtime.block_on(async {
    /// use libtmux::EnvironmentEntry;
    ///
    /// let guard = libtmux::test::TestServer::new().await?;
    /// let server = guard.server();
    ///
    /// server.set_environment("EDITOR", "hx").await?;
    /// assert!(matches!(
    ///     server.environment("EDITOR").await?,
    ///     Some(EnvironmentEntry::Set(value)) if value.as_bytes() == b"hx",
    /// ));
    ///
    /// // Separate stores: the session has no entry of its own, and reading it
    /// // does not fall back to the server. The value still reaches a process
    /// // the session starts.
    /// let session = server.new_session("separate").await?;
    /// assert_eq!(session.environment("EDITOR").await?, None);
    ///
    /// guard.shutdown().await?;
    /// # Ok::<(), Box<dyn std::error::Error>>(())
    /// # })?;
    /// # Ok(())
    /// # }
    /// ```
    pub async fn set_environment(
        &self,
        name: &str,
        value: impl Into<OsString>,
    ) -> Result<(), Error> {
        environment::set(&self.core, environment::Scope::Global, name, value.into()).await
    }

    /// Read one variable from the server's environment.
    ///
    /// tmux keeps two different things under a name: a value, and a mark
    /// saying a process started from it must not inherit the name at all.
    /// [`EnvironmentEntry`] keeps them apart, because collapsing both to
    /// absence would hide the second, which a caller sets deliberately with
    /// [`Self::hide_environment`].
    ///
    /// `None` means tmux holds nothing under the name.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux cannot be reached.
    pub async fn environment(&self, name: &str) -> Result<Option<EnvironmentEntry>, Error> {
        environment::get(&self.core, environment::Scope::Global, name).await
    }

    /// Read the server's whole environment.
    ///
    /// Costs one tmux command, read the way
    /// [`Session::environment_all`](crate::Session::environment_all)
    /// describes: each value reads exactly as [`Self::environment`] reads it.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux cannot be reached or refuses the listing,
    /// and [`Error::DecodeListing`] when the listing is not in the shape tmux
    /// prints. An empty map means the server holds nothing, never that the
    /// listing failed.
    pub async fn environment_all(&self) -> Result<BTreeMap<String, EnvironmentEntry>, Error> {
        environment::all(&self.core, environment::Scope::Global).await
    }

    /// Hide a variable from processes tmux starts.
    ///
    /// Different from [`Self::unset_environment`], which deletes the server's
    /// own entry and lets whatever tmux was started with show through. This
    /// keeps an entry and marks it, so a process started afterwards is handed
    /// an environment with the name *absent* even though the tmux server was
    /// started with one. It is what [`EnvironmentEntry::Removed`] reports.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux rejects the name.
    pub async fn hide_environment(&self, name: &str) -> Result<(), Error> {
        environment::hide(&self.core, environment::Scope::Global, name).await
    }

    /// Remove a variable from the server's environment.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux rejects the name.
    pub async fn unset_environment(&self, name: &str) -> Result<(), Error> {
        environment::unset(&self.core, environment::Scope::Global, name).await
    }

    /// Read every value an array option holds, by index.
    ///
    /// Some tmux options hold a numbered set rather than one value:
    /// `command-alias` and `terminal-overrides` are the common ones, and every
    /// hook is one too. The indices are sparse and tmux keeps the gaps, so
    /// this reports them rather than a list. An empty result means the option
    /// holds nothing.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux does not recognize the option name.
    ///
    /// # Examples
    ///
    /// ```
    /// # fn main() -> Result<(), Box<dyn std::error::Error>> {
    /// # let runtime = tokio::runtime::Builder::new_current_thread().enable_all().build()?;
    /// # runtime.block_on(async {
    /// let guard = libtmux::test::TestServer::new().await?;
    /// let server = guard.server();
    ///
    /// // Written far apart on purpose: nothing renumbers, so the gap stays.
    /// server.set_array_option("command-alias", 30, "thirty=display -p 30").await?;
    /// server.set_array_option("command-alias", 35, "five=display -p 35").await?;
    ///
    /// let aliases = server.array_option("command-alias").await?;
    /// assert_eq!(aliases.get(31), None, "the gap is tmux's, and it is kept");
    /// assert_eq!(
    ///     aliases.get(35).map(|value| value.to_string_lossy().into_owned()),
    ///     Some("five=display -p 35".to_owned()),
    /// );
    ///
    /// server.unset_array_option("command-alias", 35).await?;
    /// assert_eq!(server.array_option("command-alias").await?.get(35), None);
    ///
    /// guard.shutdown().await?;
    /// # Ok::<(), Box<dyn std::error::Error>>(())
    /// # })?;
    /// # Ok(())
    /// # }
    /// ```
    pub async fn array_option(&self, name: &str) -> Result<SparseValues<TmuxText>, Error> {
        Ok(SparseValues::from(
            options::indexed(&self.core, array_scope(name), name).await?,
        ))
    }

    /// Write one index of an array option, leaving the others alone.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux refuses the option name or the value.
    pub async fn set_array_option(
        &self,
        name: &str,
        index: u32,
        value: impl Into<OsString>,
    ) -> Result<(), Error> {
        options::set(
            &self.core,
            array_scope(name),
            &format!("{name}[{index}]"),
            value,
            false,
        )
        .await
    }

    /// Extend the value already at one index of an array option.
    ///
    /// Appends to that index's value rather than adding an entry, which is
    /// what tmux's `-a` does here.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux refuses the option name or the value.
    pub async fn append_array_option(
        &self,
        name: &str,
        index: u32,
        value: impl Into<OsString>,
    ) -> Result<(), Error> {
        options::set(
            &self.core,
            array_scope(name),
            &format!("{name}[{index}]"),
            value,
            true,
        )
        .await
    }

    /// Remove one index of an array option, leaving a gap where it was.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux refuses the option name.
    pub async fn unset_array_option(&self, name: &str, index: u32) -> Result<(), Error> {
        options::unset(&self.core, array_scope(name), &format!("{name}[{index}]")).await
    }

    /// Set one global window option to text, unchecked.
    ///
    /// [`Self::set_typed_global_window_option`] checks the value first.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux rejects the name or value.
    pub async fn set_global_window_option(
        &self,
        name: &str,
        value: impl Into<OsString>,
    ) -> Result<(), Error> {
        options::set(&self.core, options::Scope::GlobalWindow, name, value, false).await
    }

    /// Set one global window option to a typed value, checked before it is
    /// sent.
    ///
    /// The value must be the variant [`Self::typed_global_window_option`]
    /// reads back for the option; [`OptionValue`] gives the rules, and what
    /// is not checked.
    ///
    /// # Errors
    ///
    /// Returns [`Error::OptionValueRefused`] without sending anything when
    /// tmux's option table refuses the value, and
    /// [`Error::OptionScopeMismatch`] when the option is not a window option.
    /// Otherwise returns an error when tmux rejects the name or value.
    ///
    /// # Examples
    ///
    /// ```no_run
    /// # async fn example(server: &libtmux::Server) -> Result<(), libtmux::Error> {
    /// server.set_typed_global_window_option("mode-keys", "vi").await?;
    /// # Ok(())
    /// # }
    /// ```
    pub async fn set_typed_global_window_option(
        &self,
        name: &str,
        value: impl Into<OptionValue>,
    ) -> Result<(), Error> {
        options::set_typed(&self.core, options::Scope::GlobalWindow, name, value.into()).await
    }

    /// Set one global hook.
    ///
    /// Hooks live in the option tables, so [`Server::typed_global_option`]
    /// reads one back under an indexed name such as `after-new-window[0]`.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux rejects the hook name or command.
    pub async fn set_hook(&self, name: &str, command: impl Into<OsString>) -> Result<(), Error> {
        options::set_hook(&self.core, options::Scope::GlobalSession, name, command).await
    }

    /// Remove one global hook.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux rejects the hook name.
    pub async fn unset_hook(&self, name: &str) -> Result<(), Error> {
        options::unset_hook(&self.core, options::Scope::GlobalSession, name).await
    }

    /// Write a whole hook at once.
    ///
    /// [`ReplaceMode::Replace`] clears the hook first, so only what is
    /// written remains; [`ReplaceMode::Merge`] leaves entries at indices the
    /// write does not name.
    ///
    /// Sent as at most two tmux invocations rather than one per index: the
    /// first command alone, then the rest together. That is not atomic: tmux
    /// applies a shared invocation in order and stops at the first refusal,
    /// so a rejected entry leaves the ones before it written.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux rejects the name or any command.
    ///
    /// # Cancel safety
    ///
    /// Under [`ReplaceMode::Replace`] the clear and the entries are one
    /// invocation, so a drop leaves the hook as it was or fully written,
    /// never cleared and unwritten; tmux reports one status for that group,
    /// so a refusal there cannot name which command drew it. Under
    /// [`ReplaceMode::Merge`] the first entry is sent on its own, so a drop
    /// after it leaves that entry written and the rest not.
    ///
    /// # Examples
    ///
    /// ```
    /// # fn main() -> Result<(), Box<dyn std::error::Error>> {
    /// # let runtime = tokio::runtime::Builder::new_current_thread().enable_all().build()?;
    /// # runtime.block_on(async {
    /// use std::collections::BTreeMap;
    /// use libtmux::{IndexedHooks, ReplaceMode, TmuxText};
    ///
    /// let guard = libtmux::test::TestServer::new().await?;
    /// let server = guard.server();
    ///
    /// let mut entries = BTreeMap::new();
    /// entries.insert(0, TmuxText::from(b"display-message first".to_vec()));
    /// entries.insert(3, TmuxText::from(b"display-message fourth".to_vec()));
    ///
    /// server
    ///     .set_hooks("alert-bell", &IndexedHooks::from(entries), ReplaceMode::Replace)
    ///     .await?;
    ///
    /// let written = server.hook("alert-bell").await?.expect("the hook is set");
    /// assert_eq!(written.len(), 2);
    /// assert!(written.get(1).is_none(), "the gap is kept");
    ///
    /// guard.shutdown().await?;
    /// # Ok::<(), Box<dyn std::error::Error>>(())
    /// # })?;
    /// # Ok(())
    /// # }
    /// ```
    pub async fn set_hooks(
        &self,
        name: &str,
        hooks: &IndexedHooks,
        replace: ReplaceMode,
    ) -> Result<(), Error> {
        options::set_hooks(
            &self.core,
            options::Scope::GlobalSession,
            name,
            hooks,
            replace,
        )
        .await
    }

    /// Read every hook set at this server.
    ///
    /// Only hooks holding something are reported: tmux lists every hook name
    /// it knows, and the ones holding nothing are absent here rather than
    /// present and empty.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux cannot be reached or refuses the listing.
    ///
    /// # Examples
    ///
    /// ```
    /// # fn main() -> Result<(), Box<dyn std::error::Error>> {
    /// # let runtime = tokio::runtime::Builder::new_current_thread().enable_all().build()?;
    /// # runtime.block_on(async {
    /// let guard = libtmux::test::TestServer::new().await?;
    /// let server = guard.server();
    ///
    /// server.set_hook("alert-bell", "display-message rang").await?;
    /// let hooks = server.hooks().await?;
    /// assert!(hooks.contains_key("alert-bell"));
    ///
    /// guard.shutdown().await?;
    /// # Ok::<(), Box<dyn std::error::Error>>(())
    /// # })?;
    /// # Ok(())
    /// # }
    /// ```
    pub async fn hooks(&self) -> Result<BTreeMap<String, IndexedHooks>, Error> {
        options::hooks(&self.core, options::Scope::GlobalSession).await
    }

    /// Read one hook's commands, or `None` when it holds nothing.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux cannot be reached or refuses the listing.
    ///
    /// # Examples
    ///
    /// ```
    /// # fn main() -> Result<(), Box<dyn std::error::Error>> {
    /// # let runtime = tokio::runtime::Builder::new_current_thread().enable_all().build()?;
    /// # runtime.block_on(async {
    /// let guard = libtmux::test::TestServer::new().await?;
    /// let server = guard.server();
    ///
    /// assert!(server.hook("alert-bell").await?.is_none());
    /// server.set_hook("alert-bell", "display-message rang").await?;
    /// assert!(server.hook("alert-bell").await?.is_some());
    ///
    /// guard.shutdown().await?;
    /// # Ok::<(), Box<dyn std::error::Error>>(())
    /// # })?;
    /// # Ok(())
    /// # }
    /// ```
    pub async fn hook(&self, name: &str) -> Result<Option<IndexedHooks>, Error> {
        options::hook(&self.core, options::Scope::GlobalSession, name).await
    }

    /// Read one server option, decoded according to its declared kind.
    ///
    /// The one way to read a single option; [`OptionValue`] says how reads
    /// and writes fit together. `TmuxText::from(value)` recovers the exact
    /// bytes tmux stored.
    ///
    /// `None` means the option holds nothing: a built-in option that is unset,
    /// or a user option that was never set. tmux prints nothing for an option
    /// set to the empty string either, so that also reads as `None`.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux does not recognize the option name.
    pub async fn typed_option(&self, name: &str) -> Result<Option<OptionValue>, Error> {
        options::get_typed(&self.core, options::Scope::Server, name).await
    }

    /// Read one global session option, decoded according to its declared kind.
    ///
    /// Sessions inherit from this table. Absence and decoding work as in
    /// [`Self::typed_option`].
    ///
    /// # Errors
    ///
    /// Returns an error when tmux does not recognize the option name.
    pub async fn typed_global_option(&self, name: &str) -> Result<Option<OptionValue>, Error> {
        options::get_typed(&self.core, options::Scope::GlobalSession, name).await
    }

    /// Read one global window option, decoded according to its declared kind.
    ///
    /// Windows inherit from this table. Absence and decoding work as in
    /// [`Self::typed_option`].
    ///
    /// # Errors
    ///
    /// Returns an error when tmux does not recognize the option name.
    ///
    /// # Examples
    ///
    /// ```no_run
    /// # async fn example(server: &libtmux::Server) -> Result<(), libtmux::Error> {
    /// use libtmux::OptionValue;
    ///
    /// let base = server.typed_global_window_option("pane-base-index").await?;
    /// assert!(matches!(base, Some(OptionValue::Number(_))));
    /// # Ok(())
    /// # }
    /// ```
    pub async fn typed_global_window_option(
        &self,
        name: &str,
    ) -> Result<Option<OptionValue>, Error> {
        options::get_typed(&self.core, options::Scope::GlobalWindow, name).await
    }
}

