    ) => {
        define_snapshot_info!(
            SessionInfo,
            SessionFields,
            Session,
            hydrate_session_info,
            decode_session_info_inner,
            $session_target,
            SessionInfo,
            $session_baseline,
            [$($session_supplements),*]
        );
        define_snapshot_info!(
            WindowInfo,
            WindowFields,
            Window,
            hydrate_window_info,
            decode_window_info_inner,
