    plan: &FormatPlan,
    row: &ParsedRow,
) -> Result<(), FormatCodecError> {
    let mut hydrator = RowHydrator::new(plan, row);
    let mut index = 0;
    while let Some(descriptor) = plan.planned().get(index).map(|field| field.descriptor) {
        decode_marker(&mut hydrator, descriptor)?;
        index += 1;
    }
    hydrator.finish()
}

