//! Window option and hook commands.

use std::collections::BTreeMap;
use std::ffi::OsString;

use crate::internal::options;
use crate::{Error, IndexedHooks, OptionValue, ReplaceMode};

use super::Window;

impl Window {
    /// List the option names set at this window's scope.
    ///
    /// Values are not included: tmux renders them for display with three
    /// different quoting styles, so re-parsing them would be guesswork. Read
    /// each value with [`Self::typed_option`], which decodes the exact bytes.
    ///
    /// Names are `String`, not [`TmuxText`](crate::TmuxText), because tmux's
    /// own are ASCII and every option method takes one as `&str`; a user
    /// option (`@name`) lists cut at any whitespace in its name, and with
    /// U+FFFD for bytes that are not UTF-8, since `show-options` prints names
    /// unframed.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux refuses the listing.
    pub async fn option_names(&self) -> Result<Vec<String>, Error> {
        let target = self.id().to_string();
        options::names(&self.core, options::Scope::Window(&target)).await
    }

    /// Read every option set at this window, decoded by its declared kind.
    ///
    /// Costs one tmux command per option, because each value is read as the
    /// bytes tmux stored rather than the form it lists them in. Use
    /// [`Self::option_names`] when only the names are wanted, and
    /// [`Self::typed_option`] for one value.
    ///
    /// An array option keeps the indexed name tmux lists it under, so
    /// `command-alias[0]` and `command-alias[1]` are separate entries.
    ///
    /// Reports what is set *at this scope*, not what the object resolves to.
    /// A session that has set nothing of its own answers empty even though
    /// every option still has an effective value it inherits.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux cannot be reached or refuses the listing.
    /// An empty map means nothing is set, never that the listing failed.
    ///
    /// # Examples
    ///
    /// ```
    /// # fn main() -> Result<(), Box<dyn std::error::Error>> {
    /// # let runtime = tokio::runtime::Builder::new_current_thread().enable_all().build()?;
    /// # runtime.block_on(async {
    /// let guard = libtmux::test::TestServer::new().await?;
    /// let session = guard.server().new_session("opts").await?;
    /// let window = session.new_window("w").await?;
    ///
    /// window.set_option("main-pane-width", "99").await?;
    /// let options = window.options().await?;
    /// assert!(options.contains_key("main-pane-width"));
    ///
    /// guard.shutdown().await?;
    /// # Ok::<(), Box<dyn std::error::Error>>(())
    /// # })?;
    /// # Ok(())
    /// # }
    /// ```
    pub async fn options(&self) -> Result<BTreeMap<String, OptionValue>, Error> {
        let target = self.id().to_string();
        options::typed_all(&self.core, options::Scope::Window(&target)).await
    }

    /// Set one option to text, unchecked.
    ///
    /// The value is marked sensitive, so it never reaches `Debug`, an error,
    /// or a tracing span. tmux validates it; [`Self::set_typed_option`]
    /// checks it against tmux's option table first.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux rejects the name or value.
    ///
    /// Returns [`crate::Error::OptionScopeMismatch`] when tmux keeps the
    /// option in another of its tables.
    pub async fn set_option(&self, name: &str, value: impl Into<OsString>) -> Result<(), Error> {
        let target = self.id().to_string();
        options::set(
            &self.core,
            options::Scope::Window(&target),
            name,
            value,
            false,
        )
        .await
    }

    /// Set one option to a typed value, checked before it is sent.
    ///
    /// The value must be the variant [`Self::typed_option`] reads back for
    /// the option; [`OptionValue`] gives the rules, and the two writes it
    /// cannot check. The value is marked sensitive, as in
    /// [`Self::set_option`].
    ///
    /// # Errors
    ///
    /// Returns [`crate::Error::OptionValueRefused`] without sending anything
    /// when tmux's option table refuses the value.
    ///
    /// Returns [`crate::Error::OptionScopeMismatch`] when tmux keeps the
    /// option in another of its tables, and an error when tmux rejects the
    /// name or value.
    ///
    /// # Examples
    ///
    /// ```no_run
    /// # async fn example(window: &libtmux::Window) -> Result<(), libtmux::Error> {
    /// window.set_typed_option("synchronize-panes", true).await?;
    /// window.set_typed_option("main-pane-width", "50%").await?;
    /// # Ok(())
    /// # }
    /// ```
    pub async fn set_typed_option(
        &self,
        name: &str,
        value: impl Into<OptionValue>,
    ) -> Result<(), Error> {
        let target = self.id().to_string();
        options::set_typed(
            &self.core,
            options::Scope::Window(&target),
            name,
            value.into(),
        )
        .await
    }

    /// Append to one option rather than replacing it.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux rejects the name or value.
    ///
    /// Returns [`crate::Error::OptionScopeMismatch`] when tmux keeps the
    /// option in another of its tables.
    pub async fn append_option(&self, name: &str, value: impl Into<OsString>) -> Result<(), Error> {
        let target = self.id().to_string();
        options::set(
            &self.core,
            options::Scope::Window(&target),
            name,
            value,
            true,
        )
        .await
    }

    /// Remove one option, restoring whatever it inherits.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux rejects the name.
    ///
    /// Returns [`crate::Error::OptionScopeMismatch`] when tmux keeps the
    /// option in another of its tables.
    pub async fn unset_option(&self, name: &str) -> Result<(), Error> {
        let target = self.id().to_string();
        options::unset(&self.core, options::Scope::Window(&target), name).await
    }

    /// Set one hook to a tmux command.
    ///
    /// Hooks live in the same option tables, so a hook is an array option and
    /// [`Self::typed_option`] reads it under an indexed name such as
    /// `after-new-window[0]`.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux rejects the hook name or command.
    ///
    /// Returns [`crate::Error::OptionScopeMismatch`] when tmux keeps the
    /// option in another of its tables.
    pub async fn set_hook(&self, name: &str, command: impl Into<OsString>) -> Result<(), Error> {
        let target = self.id().to_string();
        options::set_hook(&self.core, options::Scope::Window(&target), name, command).await
    }

    /// Remove one hook.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux rejects the hook name.
    ///
    /// Returns [`crate::Error::OptionScopeMismatch`] when tmux keeps the
    /// option in another of its tables.
    pub async fn unset_hook(&self, name: &str) -> Result<(), Error> {
        let target = self.id().to_string();
        options::unset_hook(&self.core, options::Scope::Window(&target), name).await
    }

    /// Write a whole hook at once.
    ///
    /// [`ReplaceMode::Replace`] clears the hook first, so only what is
    /// written remains; [`ReplaceMode::Merge`] leaves entries at indices the
    /// write does not name.
    ///
    /// Sent as at most two tmux invocations rather than one per index: the
    /// first command alone, then the rest together. That is not atomic: tmux
    /// applies a shared invocation in order and stops at the first refusal,
    /// so a rejected entry leaves the ones before it written.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux rejects the name or any command.
    ///
    /// Returns [`crate::Error::OptionScopeMismatch`] when tmux keeps the
    /// option in another of its tables.
    ///
    /// # Cancel safety
    ///
    /// Under [`ReplaceMode::Replace`] the clear and the entries are one
    /// invocation, so a drop leaves the hook as it was or fully written,
    /// never cleared and unwritten; tmux reports one status for that group,
    /// so a refusal there cannot name which command drew it. Under
    /// [`ReplaceMode::Merge`] the first entry is sent on its own, so a drop
    /// after it leaves that entry written and the rest not.
    ///
    /// # Examples
    ///
    /// ```
    /// # fn main() -> Result<(), Box<dyn std::error::Error>> {
    /// # let runtime = tokio::runtime::Builder::new_current_thread().enable_all().build()?;
    /// # runtime.block_on(async {
    /// use std::collections::BTreeMap;
    /// use libtmux::{IndexedHooks, ReplaceMode, TmuxText};
    ///
    /// let guard = libtmux::test::TestServer::new().await?;
    /// let session = guard.server().new_session("hooked").await?;
    /// let window = session.active_window().await?.expect("a window");
    ///
    /// let mut entries = BTreeMap::new();
    /// entries.insert(0, TmuxText::from(b"display-message first".to_vec()));
    /// entries.insert(3, TmuxText::from(b"display-message fourth".to_vec()));
    ///
    /// window
    ///     .set_hooks("pane-died", &IndexedHooks::from(entries), ReplaceMode::Replace)
    ///     .await?;
    ///
    /// let written = window.hook("pane-died").await?.expect("the hook is set");
    /// assert_eq!(written.len(), 2);
    /// assert!(written.get(1).is_none(), "the gap is kept");
    ///
    /// guard.shutdown().await?;
    /// # Ok::<(), Box<dyn std::error::Error>>(())
    /// # })?;
    /// # Ok(())
    /// # }
    /// ```
    pub async fn set_hooks(
        &self,
        name: &str,
        hooks: &IndexedHooks,
        replace: ReplaceMode,
    ) -> Result<(), Error> {
        let target = self.id().to_string();
        options::set_hooks(
            &self.core,
            options::Scope::Window(&target),
            name,
            hooks,
            replace,
        )
        .await
    }

    /// Read one hook's commands, or `None` when it holds nothing.
    ///
    /// There is deliberately no listing counterpart at this scope. tmux does
    /// not enumerate hooks set on a window or a pane: `show-hooks` reports
    /// nothing for them, and `show-options` omits them while still listing
    /// ordinary options. A listing here could only ever answer empty, which
    /// would read as "no hooks" rather than "tmux will not say". Reading one
    /// by name works, so that is what is offered; [`crate::Server::hooks`] and
    /// [`crate::Session::hooks`] list the scopes tmux does enumerate.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux cannot be reached or refuses the listing.
    ///
    /// # Examples
    ///
    /// ```
    /// # fn main() -> Result<(), Box<dyn std::error::Error>> {
    /// # let runtime = tokio::runtime::Builder::new_current_thread().enable_all().build()?;
    /// # runtime.block_on(async {
    /// let guard = libtmux::test::TestServer::new().await?;
    /// let session = guard.server().new_session("hooked").await?;
    /// let window = session.new_window("w").await?;
    ///
    /// assert!(window.hook("pane-died").await?.is_none());
    /// window.set_hook("pane-died", "display-message rang").await?;
    /// assert!(window.hook("pane-died").await?.is_some());
    ///
    /// guard.shutdown().await?;
    /// # Ok::<(), Box<dyn std::error::Error>>(())
    /// # })?;
    /// # Ok(())
    /// # }
    /// ```
    pub async fn hook(&self, name: &str) -> Result<Option<IndexedHooks>, Error> {
        let target = self.id().to_string();
        options::hook(&self.core, options::Scope::Window(&target), name).await
    }

    /// Read one option, decoded according to what tmux declares about it.
    ///
    /// A flag comes back as [`OptionValue::Flag`] and a number as
    /// [`OptionValue::Number`], so a caller does not decide for itself that
    /// `on` means one. Everything else, including user options, stays text.
    /// The one way to read a single option; [`OptionValue`] says how reads
    /// and writes fit together.
    ///
    /// `None` means the option holds nothing at this window. A user option,
    /// whose name begins with `@`, exists only while it is set, and a built-in
    /// one always exists, so both report an unset option as `None`.
    ///
    /// # Errors
    ///
    /// Returns an error when tmux does not recognize the option name.
    pub async fn typed_option(&self, name: &str) -> Result<Option<OptionValue>, Error> {
        let target = self.id().to_string();
        options::get_typed(&self.core, options::Scope::Window(&target), name).await
    }
}

crates/tmux-mcp/src/caller.rs.content:
//! Where this server is running, and what it must not disrupt or destroy.
//!
//! tmux sets `TMUX` and `TMUX_PANE` in every process it starts, so an MCP
//! server launched from a pane can say which pane that is. Two things are
//! built on that: pane listings say which pane is the caller's own, pane input
//! refuses to reach it, and teardown tools refuse to destroy it.
//!
//! A pane id is only unique within one tmux server. `%1` on the socket this
//! process was started from and `%1` on the socket it was asked about are
//! different panes, so every comparison here weighs the socket as well.

use std::ffi::OsString;
use std::fmt;
use std::path::{Path, PathBuf};

use libtmux::ServerGeneration;

use serde::Serialize;

/// How a pane relates to the process answering the request.
///
/// Three values rather than a boolean, because "not the caller's pane" and
/// "there is no caller" are different answers and an agent acts differently on
/// each.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq, Serialize, schemars::JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum Relation {
    /// This process is not running inside tmux, so no pane is its own.
    #[default]
    Unknown,
    /// Confirmed: the same tmux server, and the same pane.
    #[serde(rename = "self")]
    Own,
    /// Some other pane, or a pane this crate cannot prove is the caller's.
    Other,
}

/// The tmux pane hosting this process, as its environment describes it.
///
/// `TMUX` carries `socket_path,server_pid,session_number`; `TMUX_PANE` carries
/// the pane id. Either both variables form one complete identity or the
/// context is malformed; only two absent variables mean detached operation,
/// and an empty variable counts as absent.
#[derive(Clone, Eq, PartialEq)]
pub struct CallerIdentity {
    socket: Option<PathBuf>,
    server_pid: Option<u32>,
    session_id: Option<String>,
    pane_id: Option<String>,
    malformed: bool,
}

impl fmt::Debug for CallerIdentity {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("CallerIdentity")
            .field("socket", &self.socket.as_ref().map(|_| "<redacted>"))
            .field("server_pid", &self.server_pid)
            .field("session_id", &self.session_id)
            .field("pane_id", &self.pane_id)
            .field("malformed", &self.malformed)
            .finish()
    }
}

fn canonical_number(value: &str) -> Option<u64> {
    let parsed = value.parse::<u64>().ok()?;
    (parsed.to_string() == value).then_some(parsed)
}

fn canonical_pane_id(value: &str) -> bool {
    value
        .parse::<libtmux::PaneId>()
        .is_ok_and(|parsed| parsed.to_string() == value)
}

impl CallerIdentity {
    /// Read the identity from this process's environment.
    ///
    /// Returns `None` when neither variable is set, which is the ordinary case
    /// for a server started outside tmux.
    #[must_use]
    pub fn from_env() -> Option<Self> {
        Self::from_values(std::env::var_os("TMUX"), std::env::var_os("TMUX_PANE"))
    }

    /// Build an identity from explicit values, as the environment would give
    /// them.
    ///
    /// Separate from [`CallerIdentity::from_env`] so the parsing can be tested
    /// without a process-wide environment, which no test can hold alone.
    #[must_use]
    pub fn from_values(tmux: Option<OsString>, pane: Option<OsString>) -> Option<Self> {
        let tmux = tmux.filter(|value| !value.is_empty());
        let pane = pane.filter(|value| !value.is_empty());
        let detached = tmux.is_none() && pane.is_none();
        if detached {
            return None;
        }

        let parsed = tmux
            .and_then(|value| value.into_string().ok())
            .zip(pane.and_then(|value| value.into_string().ok()))
            .and_then(|(tmux, pane_id)| {
                let (socket, suffix) = tmux.rsplit_once(',')?;
                let (socket, server_pid) = socket.rsplit_once(',')?;
                let socket = PathBuf::from(socket);
                let server_pid = canonical_number(server_pid)
                    .and_then(|value| u32::try_from(value).ok())
                    .filter(|value| *value != 0)?;
                let session =
                    canonical_number(suffix).and_then(|value| u32::try_from(value).ok())?;
                if !socket.is_absolute()
                    || !crate::exec::route_path_is_terminal_safe(socket.as_os_str())
                    || !canonical_pane_id(&pane_id)
                {
                    return None;
                }
                Some((socket, server_pid, format!("${session}"), pane_id))
            });

        Some(match parsed {
            Some((socket, server_pid, session_id, pane_id)) => Self {
                socket: Some(socket),
                server_pid: Some(server_pid),
                session_id: Some(session_id),
                pane_id: Some(pane_id),
                malformed: false,
            },
            None => Self {
                socket: None,
                server_pid: None,
                session_id: None,
                pane_id: None,
                malformed: true,
            },
        })
    }

    /// Whether the variables were set but do not describe one tmux pane.
    ///
    /// Pane-input and teardown tools refuse every call while this holds,
    /// because they cannot rule out reaching the caller's own pane.
    #[must_use]
    pub const fn is_malformed(&self) -> bool {
        self.malformed
    }

    /// The pane this process runs in, when tmux named one.
    #[must_use]
    pub fn pane_id(&self) -> Option<&str> {
        self.pane_id.as_deref()
    }

    /// The socket path this process was started from, when tmux named one.
    #[must_use]
    pub fn socket(&self) -> Option<&Path> {
        self.socket.as_deref()
    }

    pub(crate) fn resolve_on<'a>(
        &'a self,
        server_socket: &Path,
        generation: ServerGeneration,
        panes: &[libtmux::Pane],
    ) -> Result<Option<&'a str>, &'static str> {
        if self.malformed {
            return Err("malformed");
        }
        let (Some(socket), Some(server_pid), Some(session_id), Some(pane_id)) = (
            self.socket.as_deref(),
            self.server_pid,
            self.session_id.as_deref(),
            self.pane_id.as_deref(),
        ) else {
            return Err("incomplete");
        };
        if !same_path(socket, server_socket) {
            return Ok(None);
        }
        if server_pid != generation.pid() {
            return Err("stale server process");
        }
        if !panes.iter().any(|pane| {
            pane.id().to_string() == pane_id && pane.session_id().to_string() == session_id
        }) {
            return Err("unresolved pane and session");
        }
        Ok(Some(pane_id))
    }

    /// Whether a pane on the given server is provably this process's own.
    ///
    /// Positive only on a confirmed socket match, because this drives an
    /// annotation an agent reads as fact. Anything less is [`Relation::Other`]:
    /// a bare pane-id match across two sockets is the false positive this
    /// whole module exists to avoid.
    #[must_use]
    pub fn relation_to(&self, pane_id: &str, server_socket: Option<&Path>) -> Relation {
        if self.malformed {
            return Relation::Other;
        }
        if self.pane_id.as_deref() != Some(pane_id) {
            return Relation::Other;
        }
        if same_socket(self.socket.as_deref(), server_socket) {
            Relation::Own
        } else {
            Relation::Other
        }
    }

    /// Whether this process might be running on the given server.
    ///
    /// Malformed context and an unreadable target socket remain protected.
    /// Complete identities on a different physical socket are foreign; a
    /// socket basename alone never authenticates a caller.
    #[must_use]
    pub fn may_be_on(&self, server_socket: Option<&Path>, _socket_name: Option<&str>) -> bool {
        if self.malformed {
            return true;
        }
        let Some(caller) = self.socket.as_deref() else {
            // No socket to compare. If tmux named a pane, assume it is here.
            return self.pane_id.is_some();
        };
        let Some(target) = server_socket else {
            return true;
        };
        if same_path(caller, target) {
            return true;
        }
        false
    }
}

/// Whether two socket paths name the same socket, when both are known.
fn same_socket(caller: Option<&Path>, target: Option<&Path>) -> bool {
    match (caller, target) {
        (Some(caller), Some(target)) => same_path(caller, target),
        _ => false,
    }
}

/// Compare physical endpoints, with exact paths as the unavailable fallback.
fn same_path(left: &Path, right: &Path) -> bool {
    crate::run_request::same_endpoint(left, right)
}

#[cfg(test)]
mod tests {
    use std::ffi::OsString;
    use std::os::unix::ffi::OsStringExt as _;

    #[test]
    fn any_nonempty_caller_variable_is_not_detached() {
        for (tmux, pane) in [
            (Some(OsString::from("/tmp/socket,1,0")), None),
            (None, Some(OsString::from("%0"))),
            (Some(OsString::new()), Some(OsString::from("%0"))),
            (
                Some(OsString::from("/tmp/socket,not-a-pid,0")),
                Some(OsString::from("%0")),
            ),
        ] {
            let caller = CallerIdentity::from_values(tmux, pane)
                .expect("only two absent variables represent a detached caller");
            assert!(caller.malformed);
            assert!(caller.is_malformed());
        }
    }

    /// `TMUX= TMUX_PANE=` is how a shell un-nests tmux, and means the same as
    /// unsetting both.
    #[test]
    fn empty_caller_variables_are_detached() {
        for (tmux, pane) in [
            (Some(OsString::new()), Some(OsString::new())),
            (Some(OsString::new()), None),
            (None, Some(OsString::new())),
        ] {
            assert_eq!(CallerIdentity::from_values(tmux, pane), None);
        }
    }

    #[test]
    fn a_pane_without_a_socket_is_malformed() {
        let caller = CallerIdentity::from_values(None, Some(OsString::from("%3")))
            .expect("a present variable is not detached");
        assert!(caller.malformed);
        assert_eq!(caller.pane_id(), None);
    }

    use super::*;

    fn identity(tmux: &str, pane: &str) -> CallerIdentity {
        let caller = CallerIdentity::from_values(Some(tmux.into()), Some(pane.into()))
            .unwrap_or_else(|| unreachable!("both values are present"));
        assert!(!caller.malformed, "fixture identity is complete");
        caller
    }

    #[test]
    fn an_absent_environment_is_no_identity() {
        assert_eq!(CallerIdentity::from_values(None, None), None);
    }

    #[test]
    fn a_pane_without_tmux_is_not_usable_identity() {
        let caller = CallerIdentity::from_values(None, Some("%3".into()));
        let caller = caller.unwrap_or_else(|| unreachable!("a pane is present"));

        assert!(caller.malformed);
        assert_eq!(caller.pane_id(), None);
        assert_eq!(caller.socket(), None);
    }

    #[test]
    fn tmux_carries_socket_pid_and_session() {
        let caller = identity("/tmp/tmux-1000/a,comma,48188,10", "%3");

        assert_eq!(caller.socket(), Some(Path::new("/tmp/tmux-1000/a,comma")));
        assert_eq!(caller.server_pid, Some(48188));
        assert_eq!(caller.session_id.as_deref(), Some("$10"));
        assert_eq!(caller.pane_id(), Some("%3"));
    }

    #[test]
    fn caller_fields_require_the_exact_tmux_encoding() {
        for (tmux, pane) in [
            ("/tmp/socket,0,0", "%0"),
            ("/tmp/socket,01,0", "%0"),
            ("/tmp/socket,1,00", "%0"),
            ("/tmp/socket,1,$0", "%0"),
            ("/tmp/socket,1,4294967296", "%0"),
            ("/tmp/socket,1,0", "%00"),
            ("relative/socket,1,0", "%0"),
            ("/tmp/socket,1,0,extra", "%0"),
        ] {
            let caller = CallerIdentity::from_values(Some(tmux.into()), Some(pane.into()))
                .expect("present context");
            assert!(caller.malformed, "{tmux} {pane}");
        }
    }

    #[test]
    fn caller_socket_rejects_ascii_terminal_controls() {
        for byte in (0..=0x1f).chain([0x7f]) {
            let mut tmux = b"/tmp/socket-".to_vec();
            tmux.push(byte);
            tmux.extend_from_slice(b",1,0");
            let caller = CallerIdentity::from_values(
                Some(OsString::from_vec(tmux)),
                Some(OsString::from("%0")),
            )
            .expect("present context");
            assert!(caller.malformed, "byte {byte:#04x} was accepted");
        }
    }

    #[tokio::test]
    async fn caller_socket_hard_link_resolves_on_the_same_daemon() {
        let guard = libtmux::test::TestServer::builder()
            .start()
            .await
            .expect("tmux starts");
        let server = guard.server();
        let session = server
            .new_session("caller-hard-link")
            .await
            .expect("session starts");
        let pane = session.panes().await.expect("panes list").remove(0);
        let generation = server.generation().await.expect("server generation");
        let alias = server.socket_path().with_file_name("caller-hard-link.sock");
        std::fs::hard_link(server.socket_path(), &alias).expect("socket hard link is created");
        let caller = CallerIdentity::from_values(
            Some(
                format!(
                    "{},{},{}",
                    alias.display(),
                    generation.pid(),
                    session.id().as_ref().trim_start_matches('$')
                )
                .into(),
            ),
            Some(pane.id().as_ref().into()),
        )
        .expect("caller context is present");
        let panes = server.panes().await.expect("pane snapshot");

        assert_eq!(
            caller
                .resolve_on(server.socket_path(), generation, &panes)
                .expect("physical alias is authenticated"),
            Some(pane.id().as_ref())
        );
        std::fs::remove_file(&alias).expect("socket hard link is removed");
        guard.shutdown().await.expect("tmux fixture shuts down");
    }

    #[test]
    fn debug_surfaces_redact_the_socket_path() {
        let path = "/tmp/libtmux-rs-test/caller-debug.sock";
        let caller = identity(&format!("{path},48188,10"), "%3");
        let builder = crate::TmuxTools::builder(
            libtmux::Server::builder()
                .socket_path("/tmp/libtmux-rs-test/caller-target.sock")
                .build()
                .expect("an inert server builds"),
        )
        .caller(Some(caller.clone()));
        let surfaces = [
            format!("{caller:?}"),
            format!("{builder:?}"),
            format!("{:?}", builder.build()),
        ];

        for surface in surfaces {
            assert!(surface.contains("CallerIdentity"), "{surface}");
            assert!(!surface.contains(path), "{surface}");
        }
    }

    #[test]
    fn a_truncated_tmux_value_is_malformed() {
        let caller = CallerIdentity::from_values(Some("/tmp/sock".into()), Some("%1".into()))
            .expect("present context");

        assert!(caller.malformed);
        assert_eq!(caller.socket(), None);
    }

    #[test]
    fn extra_fields_make_the_context_malformed() {
        let caller =
            CallerIdentity::from_values(Some("/tmp/sock,1,1,extra".into()), Some("%1".into()))
                .expect("present context");

        assert!(caller.malformed);
        assert_eq!(caller.socket(), None);
    }

    #[test]
    fn the_same_pane_on_the_same_socket_is_the_callers_own() {
        let caller = identity("/tmp/sock,1,0", "%1");

        assert_eq!(
            caller.relation_to("%1", Some(Path::new("/tmp/sock"))),
            Relation::Own
        );
    }

    #[test]
    fn the_same_pane_id_on_another_socket_is_not() {
        let caller = identity("/tmp/sock-a,1,0", "%1");

        assert_eq!(
            caller.relation_to("%1", Some(Path::new("/tmp/sock-b"))),
            Relation::Other,
            "a pane id is only unique within one server"
        );
    }

    #[test]
    fn an_unprovable_socket_annotates_as_other() {
        let caller = CallerIdentity::from_values(None, Some("%1".into()));
        let caller = caller.unwrap_or_else(|| unreachable!("a pane is present"));

        assert_eq!(
            caller.relation_to("%1", Some(Path::new("/tmp/sock"))),
            Relation::Other,
            "the annotation states fact, so it declines what it cannot prove"
        );
    }

    #[test]
    fn a_different_pane_is_other() {
        let caller = identity("/tmp/sock,1,0", "%1");

        assert_eq!(
            caller.relation_to("%2", Some(Path::new("/tmp/sock"))),
            Relation::Other
        );
    }

    #[test]
    fn a_mangled_socket_is_no_evidence_rather_than_contrary_evidence() {
        // tmux writes an absolute path. Anything else reached this process
        // through something that damaged it, and reading it as "a different
        // server" would clear the way to killing the caller's own pane.
        for mangled in ["garbage-with-no-commas", "relative/path,1,0", "..,1,0"] {
            let caller = CallerIdentity::from_values(Some(mangled.into()), Some("%1".into()))
                .expect("present context");

            assert!(caller.malformed);
            assert_eq!(
                caller.socket(),
                None,
                "{mangled} should not parse as a socket"
            );
            assert!(
                caller.may_be_on(Some(Path::new("/tmp/tmux-1000/default")), Some("default")),
                "{mangled} must leave the guard cautious"
            );
            assert_eq!(
                caller.relation_to("%1", Some(Path::new("/tmp/tmux-1000/default"))),
                Relation::Other,
                "{mangled} proves nothing, so the annotation declines"
            );
        }
    }

    #[test]
    fn the_guard_blocks_what_the_annotation_declines() {
        let caller = CallerIdentity::from_values(None, Some("%1".into()));
        let caller = caller.unwrap_or_else(|| unreachable!("a pane is present"));

        assert!(
            caller.may_be_on(Some(Path::new("/tmp/sock")), Some("default")),
            "with no socket to compare, a kill must assume the worst"
        );
    }

    #[test]
    fn the_guard_blocks_when_the_target_socket_is_unreadable() {
        let caller = identity("/tmp/sock,1,0", "%1");

        assert!(caller.may_be_on(None, None));
    }

    #[test]
    fn the_guard_does_not_authenticate_a_basename_match() {
        let caller = identity("/private/tmp/tmux-1000/work,1,0", "%1");

        assert!(!caller.may_be_on(Some(Path::new("/tmp/tmux-1000/work")), Some("work")));
    }

    #[test]
    fn the_guard_clears_an_unrelated_server() {
        let caller = identity("/tmp/tmux-1000/default,1,0", "%1");

        assert!(
            !caller.may_be_on(Some(Path::new("/tmp/tmux-1000/other")), Some("other")),
            "a different socket by both path and name is a different server"
        );
    }
}

