//! Reading the command line the binary was started with.
//!
//! Hand-written rather than reached for a parser crate. There are two
//! options, and a server an agent runs is a server whose dependency list gets
//! read: a tree pulled in to format one help text is a poor trade. The flags
//! mirror tmux's own `-S` and `-L` so that someone who knows tmux already
//! knows these.

use std::ffi::OsString;
use std::path::PathBuf;

/// What the binary was asked to do.
#[derive(Debug, Default, Eq, PartialEq)]
pub struct Options {
    /// The socket path to talk to, from `-S`.
    pub socket_path: Option<PathBuf>,
    /// The socket name to talk to, from `-L`.
    pub socket_name: Option<OsString>,
}

/// Why the binary is stopping before it serves anything.
#[derive(Debug, Eq, PartialEq)]
pub enum Stop {
    /// Print the help text and exit successfully.
    Help,
    /// Print the version and exit successfully.
    Version,
    /// Complain and exit unsuccessfully.
    Misuse(
        /// The argument diagnostic printed to stderr before the binary exits.
        String,
    ),
}

/// The help text, which is also the documentation for the flags.
pub const HELP: &str = concat!(
    "tmux-mcp — serve tmux over the Model Context Protocol on stdio\n",
    "\n",
    "USAGE:\n",
    "    tmux-mcp [OPTIONS]\n",
    "\n",
    "OPTIONS:\n",
    "    -S, --socket <PATH>     Talk to the tmux server on this socket path\n",
    "    -L, --socket-name <NAME>\n",
    "                            Talk to the tmux server with this socket name\n",
    "    -h, --help              Print this help\n",
    "    -V, --version           Print the version\n",
    "\n",
    "Without -S or -L the server uses the socket LIBTMUX_SOCKET_PATH or\n",
    "LIBTMUX_SOCKET names. With neither set it passes tmux no socket, and tmux\n",
    "picks the server: the one TMUX names inside tmux, else its default socket.\n",
    "\n",
    "ENVIRONMENT:\n",
    "    LIBTMUX_SOCKET_PATH     Socket path, as -S; ignored when -S or -L is given.\n",
    "                            Wins over LIBTMUX_SOCKET when both are set\n",
    "    LIBTMUX_SOCKET          Socket name, as -L; ignored when -S or -L is given\n",
    "    LIBTMUX_TMUX_CONFIG     Absolute path of a tmux configuration file for a\n",
    "                            daemon this starts\n",
    "    LIBTMUX_TOOLSETS        Comma-separated toolsets: inspect, manage, execute,\n",
    "                            teardown. Default: the first three; empty offers\n",
    "                            none\n",
    "    LIBTMUX_TOOLS           Comma-separated tools to add to the toolsets\n",
    "    LIBTMUX_EXCLUDE_TOOLS   Comma-separated tools to remove; wins over both\n",
    "    LIBTMUX_ENVIRONMENT_VALUES\n",
    "                            Comma-separated tmux environment variables whose\n",
    "                            values tools may return. Default: none\n",
    "\n",
    "A tool left out by selection is neither listed nor callable. A malformed\n",
    "setting stops startup.\n",
    "\n",
    "The protocol runs on stdout, so anything this prints for a person goes to\n",
    "stderr, where an MCP client collects it as the server's log.\n",
);

impl Options {
    /// Read the options from arguments, excluding the program name.
    ///
    /// # Errors
    ///
    /// Returns the reason to stop before serving: the caller asked for help or
    /// the version, or passed something unusable.
    pub fn parse<I>(arguments: I) -> Result<Self, Stop>
    where
        I: IntoIterator<Item = OsString>,
    {
        let mut options = Self::default();
        let mut arguments = arguments.into_iter().peekable();

        while let Some(argument) = arguments.next() {
            let text = argument.to_string_lossy().into_owned();
            // `--flag=value` is split here so each flag below only has to
            // handle the separated form.
            let (flag, inline) = match text.split_once('=') {
                Some((flag, value)) if flag.starts_with("--") => {
                    (flag.to_owned(), Some(OsString::from(value)))
                }
                _ => (text, None),
            };

            let mut take = |flag: &str| -> Result<OsString, Stop> {
                inline.clone().map_or_else(
                    || {
                        arguments
                            .next()
                            .ok_or_else(|| Stop::Misuse(format!("{flag} needs a value")))
                    },
                    Ok,
                )
            };

            match flag.as_str() {
                "-h" | "--help" => return Err(Stop::Help),
                "-V" | "--version" => return Err(Stop::Version),
                "-S" | "--socket" => {
                    options.socket_path = Some(PathBuf::from(take("--socket")?));
                }
                "-L" | "--socket-name" => {
                    options.socket_name = Some(take("--socket-name")?);
                }
                other => {
                    return Err(Stop::Misuse(format!("unrecognised argument {other}")));
                }
            }
        }

        if options.socket_path.is_some() && options.socket_name.is_some() {
            return Err(Stop::Misuse(
                "give either --socket or --socket-name, not both".to_owned(),
            ));
        }

        Ok(options)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn parse(arguments: &[&str]) -> Result<Options, Stop> {
        Options::parse(arguments.iter().map(OsString::from))
    }

    #[test]
    fn no_arguments_is_no_opinion() {
        assert_eq!(parse(&[]), Ok(Options::default()));
    }

    #[test]
    fn a_socket_path_is_read_either_way_round() {
        let separated = parse(&["-S", "/tmp/sock"]).expect("valid");
        let inline = parse(&["--socket=/tmp/sock"]).expect("valid");

        assert_eq!(
            separated.socket_path.as_deref(),
            Some(Path::new("/tmp/sock"))
        );
        assert_eq!(inline.socket_path, separated.socket_path);
    }

    #[test]
    fn a_socket_name_mirrors_tmuxs_own_flag() {
        let parsed = parse(&["-L", "work"]).expect("valid");

        assert_eq!(parsed.socket_name.as_deref(), Some(OsStr::new("work")));
    }

    #[test]
    fn the_two_socket_flags_are_exclusive() {
        let refused = parse(&["-S", "/tmp/sock", "-L", "work"]).expect_err("refused");

        assert!(matches!(refused, Stop::Misuse(reason) if reason.contains("not both")));
    }

    #[test]
    fn a_flag_without_its_value_says_so() {
        let refused = parse(&["--socket"]).expect_err("refused");

        assert!(matches!(refused, Stop::Misuse(reason) if reason.contains("needs a value")));
    }

    #[test]
    fn help_and_version_stop_before_anything_else() {
        assert_eq!(parse(&["--help"]), Err(Stop::Help));
        assert_eq!(parse(&["-h"]), Err(Stop::Help));
        assert_eq!(parse(&["--version"]), Err(Stop::Version));
        assert_eq!(parse(&["-V"]), Err(Stop::Version));
        // Even alongside something that would otherwise be rejected.
        assert_eq!(parse(&["--help", "--nonsense"]), Err(Stop::Help));
    }

    #[test]
    fn an_unknown_argument_is_named_back() {
        let refused = parse(&["--colour=blue"]).expect_err("refused");

        assert!(matches!(refused, Stop::Misuse(reason) if reason.contains("--colour")));
    }

    #[test]
    fn the_help_text_names_every_flag() {
        for flag in [
            "-S",
            "--socket",
            "-L",
            "--socket-name",
            "-h",
            "--help",
            "-V",
            "--version",
        ] {
            assert!(HELP.contains(flag), "the help text should mention {flag}");
        }
    }

    use std::ffi::OsStr;
    use std::path::Path;
}

crates/tmux-mcp/src/exec.rs.content:
//! Running a command in a pane, and waiting for one to say something.
//!
//! Both read the pane's output stream rather than its screen. A screen is what
//! survived rendering; the stream is everything the program wrote, in the
//! order it wrote it, including what has already scrolled away. Nothing here
//! polls, and nothing here depends on tmux still holding a line in scrollback.

use std::time::Duration;

use tokio_util::sync::CancellationToken;

use libtmux::{CaptureOptions, ControlLimits, ControlModeErrorKind, Error, Pane};
use regex::bytes::Regex;
use serde::Serialize;

use crate::echo::{EchoKey, PaneEchoes};
use crate::retained::MAX_BYTES as OUTPUT_LIMIT;
#[cfg(test)]
use crate::retained::{COMPACT_AFTER, RetainedBytes};
use crate::text::TextFilter;
#[cfg(test)]
use crate::text::readable_from;

const MAX_PATTERNS: usize = 32;
const MAX_PATTERN_BYTES: usize = 4_096;
const MAX_TOTAL_PATTERN_BYTES: usize = 16_384;

/// The shared echo record and this pane's key into it, bundled so threading
/// both through `wait_for_text`'s internal calls does not itself run into
/// clippy's argument-count limit.
#[derive(Clone, Copy)]
pub(crate) struct EchoContext<'a> {
    pub(crate) echoes: &'a PaneEchoes,
    pub(crate) key: Option<&'a EchoKey>,
}

mod run;

#[cfg(test)]
pub(crate) use run::observing_prepared_shutdowns;
#[cfg(test)]
use run::{
    FrameError, Scanner, TRAP_DECLARATION_LIMIT, find, frame_path, frame_with_random,
    inherited_trap_capture, quote_shell_word, render_payload, stage_frame, staged_line,
};
pub(crate) use run::{
    PrepareRunError, RunDispatch, RunProgress, prepare_run, readable, route_is_terminal_safe,
    route_path_is_terminal_safe,
};

/// How a run finished.
///
/// Split from the wait outcomes rather than shared with them: a run cannot
/// match a pattern and a wait cannot report a missing shell, and a vocabulary
/// carrying both would have an agent checking for answers that never come.
#[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize, schemars::JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum RunOutcome {
    /// The command ran to completion and reported its status.
    Completed,
    /// The time the caller allowed ran out.
    ///
    /// This ends the waiting, not the command. The pane stays reserved for it
    /// until it ends, so other pane input is refused; `send_keys` with keys
    /// `["C-c"]` alone interrupts it.
    Deadline,
    /// The pane stopped writing for good.
    PaneClosed,
    /// The client withdrew the request while the run was still going.
    Cancelled,
    /// The pane never acknowledged the command.
    ///
    /// The keys were sent but the opening sentinel never came back. That is
    /// what a pane looks like when it is not at a shell prompt: sitting in an
    /// editor or a REPL, or still running something an earlier call left
    /// behind. The text was typed into whatever is there.
    ///
    /// The evidence is absence, so a deadline too short for the pane's shell
    /// to have echoed anything yet looks the same. Read it as "nothing came
    /// back in the time allowed" and check the pane with `snapshot_pane`
    /// before concluding it is stuck.
    NoShell,
}

/// How a wait for text finished.
#[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize, schemars::JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum WaitOutcome {
    /// A wanted pattern was already in the pane's output before this began
    /// watching, on a row above the one still being typed into, and is not
    /// a line this server itself submitted moments earlier.
    ///
    /// A wait only sees what a pane writes after it starts, so this is never
    /// folded into [`Self::Matched`]: the same pattern printed moments
    /// earlier -- an earlier command's own output, say -- can already be
    /// sitting there, and a caller that treated that as a fresh match would
    /// act on something that happened before this call, not because of it.
    /// A line this server typed and submitted with `send_keys` is discounted
    /// rather than reported here or as [`Self::Matched`], for a short time
    /// after it was submitted.
    PresentAtEntry,
    /// A wanted pattern's only occurrence is the row still being typed
    /// into: text this server (or a person sharing the pane) sent and has
    /// not submitted, not anything that has run.
    ///
    /// Submit it, then wait again: the next wait sees the command's own
    /// output on a row above a new one still being typed into, which is
    /// [`Self::PresentAtEntry`] or [`Self::Matched`] depending on when it
    /// arrived, never this -- and never the submitted line's own echo,
    /// which stays discounted for a short time after.
    Pending,
    /// A pattern matched, in output that arrived after the wait attached.
    Matched,
    /// A stop pattern matched, so the wait ended early.
    Stopped,
    /// The time the caller allowed ran out.
    Deadline,
    /// The pane stopped writing for good: it closed, or the server holding it
    /// exited. `text` holds the output seen up to then.
    PaneClosed,
    /// The control stream ended while the pane was still alive, for example
    /// because its client was detached.
    ///
    /// Nothing says the pane stopped, only that this wait can no longer see
    /// it. Wait again to watch it afresh; `text` holds the output seen up to
    /// the loss. The polling path, used below tmux 3.7, has no stream to lose.
    StreamLost,
    /// The client withdrew the request while the wait was still running.
    Cancelled,
}

/// What a command did.
#[derive(Clone, Debug, Serialize, schemars::JsonSchema)]
pub struct RunView {
    /// The pane the command ran in.
    pub pane: String,
    /// How the run finished.
    pub outcome: RunOutcome,
    /// The command's exit status, when it completed.
    ///
    /// Absent when the run did not complete, and when the command was killed
    /// by a signal rather than exiting.
    pub exit_status: Option<i32>,
    /// The retained tail of command output, stdout and stderr interleaved.
    ///
    /// This is the raw output stream with escape sequences removed, not the
    /// rendered screen: a line redrawn in place, such as a progress bar,
    /// repeats. Check `truncated` before treating it as complete.
    /// `capture_pane` shows the screen.
    pub output: String,
    /// How many bytes that was, before any truncation.
    pub bytes: usize,
    /// Whether the output was truncated from the front.
    pub truncated: bool,
}

/// What a pane said while it was watched for a pattern.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct WaitView {
    /// The pane that was watched.
    pub pane: String,
    /// How the wait finished.
    pub outcome: WaitOutcome,
    /// Which pattern matched, indexed into the list it came from.
    pub matched_index: Option<usize>,
    /// The pattern that matched, as it was given.
    pub matched_pattern: Option<String>,
    /// Retained stream text, or captured screen text on the polling path.
    ///
    /// Streamed results are not the rendered screen: escape sequences are
    /// removed and a line redrawn in place repeats. `capture_pane` shows the
    /// screen. Below tmux 3.7 this is the last visible screen read instead;
    /// a present-at-entry match can also return captured screen text.
    pub text: String,
    /// How many bytes arrived, before filtering or truncation.
    pub bytes: usize,
}

/// A set of patterns to look for in a pane's output.
pub(crate) struct Patterns {
    compiled: Vec<Regex>,
    sources: Vec<String>,
}

impl Patterns {
    /// Compile patterns, as literal text or as regular expressions.
    ///
    /// # Errors
    ///
    /// Returns the offending pattern and the reason when one will not compile.
    pub(crate) fn compile(
        sources: &[String],
        regex: bool,
        match_case: bool,
    ) -> Result<Self, (String, String)> {
        if sources.len() > MAX_PATTERNS {
            return Err((
                "set".to_owned(),
                format!("contains more than {MAX_PATTERNS} patterns"),
            ));
        }
        let mut compiled = Vec::with_capacity(sources.len());
        let mut total_bytes = 0_usize;
        for (index, source) in sources.iter().enumerate() {
            if source.len() > MAX_PATTERN_BYTES {
                return Err((
                    format!("{}", index + 1),
                    format!("exceeds {MAX_PATTERN_BYTES} bytes"),
                ));
            }
            total_bytes = total_bytes.saturating_add(source.len());
            if total_bytes > MAX_TOTAL_PATTERN_BYTES {
                return Err((
                    "set".to_owned(),
                    format!("exceeds {MAX_TOTAL_PATTERN_BYTES} bytes in total"),
                ));
            }
            let body = if regex {
                source.clone()
            } else {
                regex::escape(source)
            };
            let expression = if match_case {
                body
            } else {
                format!("(?i){body}")
            };
            match Regex::new(&expression) {
                Ok(pattern) => compiled.push(pattern),
                Err(error) => return Err((source.clone(), error.to_string())),
            }
        }

        Ok(Self {
            compiled,
            sources: sources.to_vec(),
        })
    }

    /// Whether any pattern was given.
    fn is_empty(&self) -> bool {
        self.compiled.is_empty()
    }

    /// The first pattern that matches, with the index it was given at.
    pub(crate) fn first_match(&self, haystack: &[u8]) -> Option<(usize, &str)> {
        self.compiled
            .iter()
            .position(|pattern| pattern.is_match(haystack))
            .map(|index| (index, self.sources[index].as_str()))
    }
}

/// Watch a pane until a pattern matches, a stop pattern matches, or time runs
/// out.
///
/// # Errors
///
/// Returns an error when the pane cannot be watched or read.
pub(crate) async fn wait_for_text(
    server: &libtmux::Server,
    pane: &Pane,
    patterns: &Patterns,
    stops: &Patterns,
    timeout: Duration,
    cancelled: &CancellationToken,
    echo: EchoContext<'_>,
) -> Result<WaitView, Error> {
    // Chosen from the daemon's version before any control client is
    // attempted: below 3.7 a stream cannot be acquired safely, and the screen
    // can be read by polling instead of refusing the wait.
    let streams = server
        .daemon_version()
        .await?
        .has_behavior(&libtmux::since::CONTROL_ACQUISITION);
    if !streams {
        return wait_for_text_polling(pane, patterns, stops, timeout, cancelled, echo).await;
    }
    wait_for_text_with_limits(
        pane,
        patterns,
        stops,
        timeout,
        cancelled,
        ControlLimits::default(),
        echo,
    )
    .await
}

/// How often the polling wait reads the screen.
const POLL_INTERVAL: Duration = Duration::from_millis(120);

/// A [`wait_for_text`] that polls the screen, for a daemon below the
/// control-acquisition floor.
///
/// It reads the screen on an interval instead of streaming the pane's output.
/// The view differs from a stream's in one way a caller can see: `text` is
/// the screen as last read, not the bytes written since the wait began, and a
/// pattern that appears and scrolls off between two reads is missed. A match
/// is confirmed the same way a stream's is, against rows above the one still
/// being typed into and discounting this server's own echo.
async fn wait_for_text_polling(
    pane: &Pane,
    patterns: &Patterns,
    stops: &Patterns,
    timeout: Duration,
    cancelled: &CancellationToken,
    echo: EchoContext<'_>,
) -> Result<WaitView, Error> {
    if let Some(view) = read_present_at_entry(pane, patterns, echo).await? {
        return Ok(view);
    }
    let baseline = Screen::capture(pane).await.map(|screen| screen.whole());
    let mut sticky: Vec<Vec<u8>> = Vec::new();
    let deadline = tokio::time::Instant::now() + timeout;
    let pane_id = pane.id().to_string();
    let view = |outcome, found: Option<(usize, &str)>, text: Vec<u8>| WaitView {
        pane: pane_id.clone(),
        outcome,
        matched_index: found.map(|(index, _)| index),
        matched_pattern: found.map(|(_, source)| source.to_owned()),
        bytes: text.len(),
        text: String::from_utf8_lossy(&text).into_owned(),
    };
    let mut last = Vec::new();
    loop {
        if cancelled.is_cancelled() {
            return Ok(view(WaitOutcome::Cancelled, None, last));
        }
        let Some(screen) = Screen::capture(pane).await else {
            return Ok(view(WaitOutcome::PaneClosed, None, last));
        };
        let whole = screen.whole();
        if let Some(found) = stops.first_match(&whole) {
            return Ok(view(WaitOutcome::Stopped, Some(found), whole));
        }
        if let Some(key) = echo.key {
            for line in echo.echoes.snapshot(key) {
                if !sticky.contains(&line) {
                    sticky.push(line);
                }
            }
        }
        let mut haystack = crate::echo::mask(&screen.above, &sticky);
        if !echo.key.is_some_and(|key| echo.echoes.has_pending(key)) {
            haystack.extend_from_slice(&screen.pending);
        }
        if patterns.is_empty() {
            if baseline.as_deref() != Some(whole.as_slice()) && !whole.is_empty() {
                return Ok(view(WaitOutcome::Matched, None, whole));
            }
        } else if let Some(found) = patterns.first_match(&haystack) {
            return Ok(view(WaitOutcome::Matched, Some(found), whole));
        }
        last = whole;
        tokio::select! {
            biased;
            () = cancelled.cancelled() => {}
            () = tokio::time::sleep_until(deadline.min(tokio::time::Instant::now() + POLL_INTERVAL)) => {}
        }
        if tokio::time::Instant::now() >= deadline {
            return Ok(view(WaitOutcome::Deadline, None, last));
        }
    }
}

/// Like [`wait_for_text`], with explicit control-mode frame budgets.
///
/// Every real caller wants [`wait_for_text`]'s default: this exists so a test
/// can shrink the budget enough to force the frame-too-large shutdown error
/// [`wait_for_text`] propagates instead of tolerating -- a branch no MCP
/// tool argument can reach, since exposing a protocol-tuning knob to a
/// caller of the tool would leak an implementation detail into its surface.
///
/// Split from [`wait_on_output`] at the attach point so a test driving a
/// tiny budget can send its adversarial output only once attaching has
/// provably finished, rather than racing a fixed delay against it.
pub(crate) async fn wait_for_text_with_limits(
    pane: &Pane,
    patterns: &Patterns,
    stops: &Patterns,
    timeout: Duration,
    cancelled: &CancellationToken,
    limits: ControlLimits,
    echo: EchoContext<'_>,
) -> Result<WaitView, Error> {
    // Attached first: a pattern that arrives while the screen is being read
    // must still be seen. Reading first would lose one that landed between
    // the capture and the attach, and wait out the deadline over output that
    // did arrive. One landing in that gap is reported as present at entry
    // instead, which is still true of the screen.
    let output = pane.stream_output_with_limits(limits).await?;
    if let Some(view) = read_present_at_entry(pane, patterns, echo).await? {
        // The answer is already in hand; a failure closing a stream nothing
        // read does not change it.
        let _ = output.shutdown().await;
        return Ok(view);
    }
    wait_on_output(pane, output, patterns, stops, timeout, cancelled, echo).await
}

/// Whether `pane` still exists and is running, as the daemon reports now.
///
/// A daemon that cannot answer -- it exited, or the pane is gone -- is not
/// live.
async fn pane_is_live(pane: &Pane) -> bool {
    pane.format("#{pane_dead}")
        .await
        .is_ok_and(|dead| dead.to_string_lossy().trim() == "0")
}

/// One pane's screen, split at the row still being typed into.
///
/// Two tmux round trips read this, not one: the cursor row first, then the
/// screen. They are not atomic, so a line arriving between the two can only
/// move the cursor down and make `pending` cover a later row -- excluding
/// more from `above`, never less -- which is the safe direction to be wrong
/// in.
struct Screen {
    /// Every visible row above the one still being typed into, each
    /// terminated with a newline: completed output, never text this server
    /// or a person sent and has not submitted.
    above: Vec<u8>,
    /// The row still being typed into, terminated with a newline to match
    /// `above`'s rows.
    pending: Vec<u8>,
}

impl Screen {
    /// Capture `pane`'s current screen, split at its cursor row.
    ///
    /// `None` when the pane cannot be read; the same failure surfaces again
    /// from whatever the caller does next.
    async fn capture(pane: &Pane) -> Option<Self> {
        let cursor_row: usize = pane
            .format("#{cursor_y}")
            .await
            .ok()?
            .to_string_lossy()
            .trim()
            .parse()
            .ok()?;
        // Rows the pane wrapped are joined, so a pattern split across a wrap
        // is one line to match. The capture ends at the cursor row, which
        // makes the last joined line the one still being typed into, however
        // many rows it spans; counting rows against joined lines would not.
        // Trailing spaces are dropped from each line as an unjoined capture
        // drops them.
        let end = i32::try_from(cursor_row).ok()?;
        let lines = pane
            .capture_with(CaptureOptions::visible().join_wrapped().end(end))
            .await
            .ok()?;
        let trimmed = |line: &[u8]| -> Vec<u8> { line.trim_ascii_end().to_vec() };

        let mut above = Vec::new();
        let completed = lines.len().saturating_sub(1);
        for line in lines.iter().take(completed) {
            above.extend_from_slice(&trimmed(line.as_bytes()));
            above.push(b'\n');
        }
        let mut pending = lines
            .last()
            .map_or_else(Vec::new, |line| trimmed(line.as_bytes()));
        pending.push(b'\n');

        Some(Self { above, pending })
    }

    /// Both halves, in screen order, for a view that reports the whole
    /// thing rather than only whichever half matched.
    fn whole(&self) -> Vec<u8> {
        let mut all = self.above.clone();
        all.extend_from_slice(&self.pending);
        all
    }
}

/// Report a wanted pattern already in the pane's output, or still only on
/// the row being typed into, before any stream attaches to watch for one
/// arriving.
///
/// See [`WaitOutcome::PresentAtEntry`] and [`WaitOutcome::Pending`] for why
/// these are distinct outcomes from [`WaitOutcome::Matched`] rather than a
/// flag alongside it.
async fn read_present_at_entry(
    pane: &Pane,
    patterns: &Patterns,
    echo: EchoContext<'_>,
) -> Result<Option<WaitView>, Error> {
    // No patterns means "wait for anything at all", which nothing already on
    // screen can pre-empt: there is nothing yet to call present.
    if patterns.is_empty() {
        return Ok(None);
    }

    // A screen that cannot be read is not a reason to refuse to wait; the
    // same failure surfaces from the attach right after this.
    let Some(screen) = Screen::capture(pane).await else {
        return Ok(None);
    };

    // A line this server itself submitted moments ago -- before this wait
    // even attached -- is not evidence of anything the pane did; discount it
    // the same way a live match is discounted below. The row still being
    // typed into is never masked: nothing not yet submitted is ever in
    // `recent`.
    let recent = echo
        .key
        .map(|key| echo.echoes.snapshot(key))
        .unwrap_or_default();
    let masked_above = crate::echo::mask(&screen.above, &recent);

    // Nothing of this server's own is unsubmitted, so the row the cursor
    // sits on is not mid-typing either -- reported the same as `above`
    // rather than `pending`, since it is not this server's own question.
    // This is what keeps a command whose output does not end in a newline
    // (so the next prompt lands on the same row) from being hidden forever.
    let pending_outcome = if echo.key.is_some_and(|key| echo.echoes.has_pending(key)) {
        WaitOutcome::Pending
    } else {
        WaitOutcome::PresentAtEntry
    };
    let outcome = patterns
        .first_match(&masked_above)
        .map(|found| (WaitOutcome::PresentAtEntry, found))
        .or_else(|| {
            patterns
                .first_match(&screen.pending)
                .map(|found| (pending_outcome, found))
        });
    let Some((outcome, (index, source))) = outcome else {
        return Ok(None);
    };
    let whole = screen.whole();

    Ok(Some(WaitView {
        pane: pane.id().to_string(),
        outcome,
        matched_index: Some(index),
        matched_pattern: Some(source.to_owned()),
        text: String::from_utf8_lossy(&whole).into_owned(),
        bytes: whole.len(),
    }))
}

/// Confirm a fresh match against `pane`'s completed rows, discounting every
/// line `echoes` has recorded for it.
///
/// `sticky` accumulates every echo seen across the whole wait, not only this
/// call's snapshot: `echoes` ages a record out on its own schedule (10
/// seconds), and a wait may run longer than that. Losing the record mid-wait
/// must not resurrect the very false match it existed to prevent, so once an
/// echo is seen it stays discounted for the rest of this call.
async fn confirmed_above(
    pane: &Pane,
    patterns: &Patterns,
    echo: EchoContext<'_>,
    sticky: &mut Vec<Vec<u8>>,
) -> bool {
    if let Some(key) = echo.key {
        for line in echo.echoes.snapshot(key) {
            if !sticky.contains(&line) {
                sticky.push(line);
            }
        }
    }
    let Some(screen) = Screen::capture(pane).await else {
        return false;
    };
    let mut haystack = crate::echo::mask(&screen.above, sticky);
    // Nothing of this server's own is unsubmitted here, so whatever is on
    // this row is not mid-typing -- most often a command's own output that
    // did not end in a newline and left the next prompt on the same row,
    // which the position rule alone would otherwise hide forever.
    if !echo.key.is_some_and(|key| echo.echoes.has_pending(key)) {
        haystack.extend_from_slice(&screen.pending);
    }
    patterns.first_match(&haystack).is_some()
}

/// The read loop [`wait_for_text_with_limits`] runs once attached.
async fn wait_on_output(
    pane: &Pane,
    mut output: libtmux::control::PaneOutput,
    patterns: &Patterns,
    stops: &Patterns,
    timeout: Duration,
    cancelled: &CancellationToken,
    echo: EchoContext<'_>,
) -> Result<WaitView, Error> {
    let mut filter = TextFilter::new();
    let mut text: Vec<u8> = Vec::new();
    let mut bytes = 0usize;
    let mut outcome = WaitOutcome::Deadline;
    let mut matched_index = None;
    let mut matched_pattern = None;
    let mut sticky_echoes: Vec<Vec<u8>> = Vec::new();
    let deadline = tokio::time::Instant::now() + timeout;

    loop {
        let chunk = tokio::select! {
            biased;
            // Checked first so a request cancelled while output is already
            // waiting still stops, rather than reading one more chunk.
            () = cancelled.cancelled() => {
                outcome = WaitOutcome::Cancelled;
                break;
            }
            chunk = tokio::time::timeout_at(deadline, output.next_chunk()) => chunk,
        };
        match chunk {
            Ok(Some(chunk)) => {
                bytes = bytes.saturating_add(chunk.len());
                filter.push(&chunk, &mut text);

                if let Some((index, source)) = stops.first_match(&text) {
                    outcome = WaitOutcome::Stopped;
                    matched_index = Some(index);
                    matched_pattern = Some(source.to_owned());
                    break;
                }
                // No patterns means "wait for anything at all", which any
                // output satisfies.
                if patterns.is_empty() {
                    if !text.is_empty() {
                        outcome = WaitOutcome::Matched;
                        break;
                    }
                } else if let Some((index, source)) = patterns.first_match(&text) {
                    // Fresh bytes on this connection are not necessarily a
                    // submitted line: the kernel echoes what was typed at
                    // once, and a shell's line editor re-prints the buffer
                    // when it starts reading, both genuinely new output that
                    // can still be sitting on the row being typed into.
                    // Confirmed only once the *current* screen shows the
                    // pattern above that row, discounting a line this server
                    // has itself recently submitted there.
                    let confirmed = confirmed_above(pane, patterns, echo, &mut sticky_echoes).await;
                    if confirmed {
                        outcome = WaitOutcome::Matched;
                        matched_index = Some(index);
                        matched_pattern = Some(source.to_owned());
                        break;
                    }
                }

                if text.len() > OUTPUT_LIMIT {
                    let excess = text.len() - OUTPUT_LIMIT;
                    text.drain(..excess);
                }
            }
            Ok(None) => {
                // The stream ending says the wait can no longer see the pane,
                // not that the pane stopped: a detached control client ends
                // it too. Only a pane that cannot be read, or one tmux holds
                // dead, has closed.
                outcome = if pane_is_live(pane).await {
                    WaitOutcome::StreamLost
                } else {
                    WaitOutcome::PaneClosed
                };
                break;
            }
            Err(_) => break,
        }
    }

    let pane_id = output.pane().to_string();
    // Ordinary EOF (`Closed`) is tolerated: the pane stopped being read, so
    // that alone is not a failure. Any other shutdown error -- frame budget,
    // timeout, executor shutdown -- is real and discards the view above.
    if let Err(error) = output.shutdown().await
        && !matches!(
            error,
            Error::ControlMode {
                kind: ControlModeErrorKind::Closed,
                ..
            }
        )
    {
        return Err(error);
    }

    // A chunk can arrive in the same instant the deadline elapses; without
    // this, that race would report `Deadline` while `text` already holds a
    // match, the same shape the .NET port hit.
    let (mut outcome, mut matched_index, mut matched_pattern) =
        reconcile_deadline(outcome, matched_index, matched_pattern, patterns, &text);
    // `reconcile_deadline` reads the same accumulated buffer the main loop
    // does, and is subject to the same trap: the promotion it just made can
    // still be the pane's own not-yet-submitted line racing the deadline,
    // not a genuine match. Confirmed the same way, against the row still
    // being typed into, or the promotion is undone.
    if matches!(outcome, WaitOutcome::Matched)
        && !confirmed_above(pane, patterns, echo, &mut sticky_echoes).await
    {
        outcome = WaitOutcome::Deadline;
        matched_index = None;
        matched_pattern = None;
    }

    Ok(WaitView {
        pane: pane_id,
        outcome,
        matched_index,
        matched_pattern,
        text: String::from_utf8_lossy(&text).into_owned(),
        bytes,
    })
}

/// Reclassify a timed-out wait as matched when the buffer it is about to
/// report already contains a pattern.
///
/// Only `Deadline` is reconsidered: `Stopped`, `PaneClosed`, and `Cancelled`
/// already carry their own reason and are returned unchanged.
fn reconcile_deadline(
    outcome: WaitOutcome,
    matched_index: Option<usize>,
    matched_pattern: Option<String>,
    patterns: &Patterns,
    text: &[u8],
) -> (WaitOutcome, Option<usize>, Option<String>) {
    if !matches!(outcome, WaitOutcome::Deadline) {
        return (outcome, matched_index, matched_pattern);
    }
    match patterns.first_match(text) {
        Some((index, source)) => (WaitOutcome::Matched, Some(index), Some(source.to_owned())),
        None => (outcome, matched_index, matched_pattern),
    }
}

