    stopped_at: Option<usize>,
    truncated: bool,
    truncated_bytes: usize,
    on_error: OnError,
}

#[derive(Default)]
struct ByteCounter(usize);

impl io::Write for ByteCounter {
    fn write(&mut self, bytes: &[u8]) -> io::Result<usize> {
        self.0 = self.0.saturating_add(bytes.len());
        Ok(bytes.len())
    }

    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}

#[derive(Clone)]
struct ReadBatchWire {
    request_id: rmcp::model::RequestId,
    result_type_supported: bool,
}

impl Default for ReadBatchWire {
    fn default() -> Self {
        Self {
            request_id: rmcp::model::RequestId::Number(0),
            result_type_supported: true,
        }
    }
}

impl ReadBatchWire {
    fn from_context(context: &RequestContext<rmcp::RoleServer>) -> Self {
        let result_type_supported = context.protocol_version().as_ref().is_some_and(|version| {
            version.as_str() >= rmcp::model::ProtocolVersion::V_2026_07_28.as_str()
        });
        Self {
            request_id: context.id.clone(),
            result_type_supported,
        }
    }

    fn response_bytes<T: Serialize>(&self, batch: &T) -> usize {
        let Ok(value) = serde_json::to_value(batch) else {
            return usize::MAX;
        };
        let mut result = rmcp::model::ServerResult::CallToolResult(
            rmcp::model::CallToolResult::structured(value),
        );
        if !self.result_type_supported {
            result.strip_result_type_for_legacy_peer();
        }
        let response = rmcp::model::ServerJsonRpcMessage::response(result, self.request_id.clone());
        let mut bytes = ByteCounter::default();
        serde_json::to_writer(&mut bytes, &response)
            .map_or(usize::MAX, |()| bytes.0.saturating_add(1))
    }
}

struct ReadBatchAccumulator {
    results: Vec<BatchItem>,
    truncated: bool,
    truncated_bytes: usize,
    stopped_at: Option<usize>,
    on_error: OnError,
    wire: ReadBatchWire,
}

impl Default for ReadBatchAccumulator {
    fn default() -> Self {
        Self::new(OnError::Stop)
    }
}

impl ReadBatchAccumulator {
    fn new(on_error: OnError) -> Self {
        Self::for_wire(on_error, ReadBatchWire::default())
    }

    fn for_request(on_error: OnError, context: &RequestContext<rmcp::RoleServer>) -> Self {
        Self::for_wire(on_error, ReadBatchWire::from_context(context))
    }

    const fn for_wire(on_error: OnError, wire: ReadBatchWire) -> Self {
        Self {
            results: Vec::new(),
            truncated: false,
            truncated_bytes: 0,
            stopped_at: None,
            on_error,
            wire,
        }
    }

    fn push(&mut self, item: BatchItem) -> bool {
        self.results.push(item);
        self.fit()
    }

    fn fit(&mut self) -> bool {
        while self.response_bytes() > READ_BATCH_MAX_BYTES {
            if let Some(item) = self.results.iter_mut().find(|item| item.result.is_some()) {
                let removed = item
                    .result
                    .as_ref()
                    .and_then(|result| serde_json::to_vec(result).ok())
                    .map_or(0, |encoded| encoded.len());
                item.result = None;
                item.result_truncated = true;
                self.truncated_bytes = self.truncated_bytes.saturating_add(removed);
                self.truncated = true;
                continue;
            }
            if let Some(item) = self.results.iter_mut().find(|item| {
                item.error
                    .as_ref()
                    .is_some_and(|error| error.message != READ_BATCH_TRUNCATED_ERROR)
            }) {
                let Some(error) = item.error.as_mut() else {
                    return false;
                };
                let before = serde_json::to_vec(error).map_or(0, |encoded| encoded.len());
                *error = ErrorData::new(error.code, READ_BATCH_TRUNCATED_ERROR, None);
                let after = serde_json::to_vec(error).map_or(0, |encoded| encoded.len());
                item.result_truncated = true;
                self.truncated_bytes = self
                    .truncated_bytes
                    .saturating_add(before.saturating_sub(after));
                self.truncated = true;
                continue;
            }
            return false;
        }
        true
    }

    fn response_bytes(&self) -> usize {
        let succeeded = self.results.iter().filter(|item| item.success).count();
        let view = BatchResultRef {
            failed: self.results.len() - succeeded,
            succeeded,
            results: &self.results,
            stopped_at: self.stopped_at,
            truncated: self.truncated,
            truncated_bytes: self.truncated_bytes,
            on_error: self.on_error,
        };
        self.wire.response_bytes(&view)
    }

    fn stop_at(&mut self, index: usize) {
        self.stopped_at = Some(index);
        let _ = self.fit();
    }

    fn finish(self) -> BatchResult {
        BatchResult::from_results(
            self.results,
            self.on_error,
            self.stopped_at,
            self.truncated,
            self.truncated_bytes,
        )
    }
}

