use std::time::{Duration, Instant};

use libtmux::{CaptureOptions, Command, TmuxText};
use rmcp::handler::server::wrapper::{Json, Parameters};
use rmcp::{tool, tool_router};

use crate::exec::Patterns;
use crate::{
    Branch, BranchPane, BranchWindow, Capture, CapturePaneArgs, Environment, EnvironmentEntry,
    EnvironmentState, Hook, Hooks, Marks, MatchView, Matches, OptionArgs, OptionValue, Panes,
    SearchPanesArgs, Sessions, ShowEnvironmentArgs, ShowHooksArgs, Snapshot, SnapshotArgs,
    TmuxTools, Tree, Windows,
};

use super::error::{ToolError, bad_input, tmux_error};
use super::{OptionScope, lossy, lossy_optional};

/// Separates the fields of a `snapshot_pane` format query.
///
/// U+241E rather than an ASCII control byte because tmux copies valid UTF-8
/// through verbatim, while `vis()` would render a control byte as the literal
/// text `\036` on some builds.
const SEPARATOR: &str = "\u{241e}";

/// The most matches a single `search_panes` call will report.
///
/// A pattern like `.` matches every line of every pane, and an agent that
/// asked for that wants a signal, not a transcript of the server.
const SEARCH_MATCHES: usize = 200;
const SEARCH_BYTES: usize = 1 << 20;
const SEARCH_PANES: usize = 64;
const SEARCH_LINES: usize = 8192;
const SEARCH_MATCH_TIME: Duration = Duration::from_millis(250);
const SEARCH_CAPTURE_TIME: Duration = Duration::from_secs(5);

struct SearchBudget {
    remaining_bytes: usize,
    remaining_panes: usize,
    remaining_lines: usize,
    remaining_match_time: Duration,
    remaining_capture_time: Duration,
    capped: bool,
}

impl SearchBudget {
    const fn new() -> Self {
        Self {
            remaining_bytes: SEARCH_BYTES,
            remaining_panes: SEARCH_PANES,
            remaining_lines: SEARCH_LINES,
            remaining_match_time: SEARCH_MATCH_TIME,
            remaining_capture_time: SEARCH_CAPTURE_TIME,
            capped: false,
        }
    }

    fn take(&mut self, bytes: usize) -> bool {
        if self.remaining_lines == 0 || bytes > self.remaining_bytes {
            self.capped = true;
            false
        } else {
            self.remaining_lines -= 1;
            self.remaining_bytes -= bytes;
            true
        }
    }

    fn begin_pane(&mut self) -> bool {
        if self.remaining_panes == 0 {
            self.capped = true;
            false
        } else {
            self.remaining_panes -= 1;
            true
        }
    }

    fn capture_time(&mut self) -> Option<Duration> {
        if self.remaining_capture_time.is_zero() {
            self.capped = true;
            None
        } else {
            Some(self.remaining_capture_time)
        }
    }

    fn charge_capture(&mut self, elapsed: Duration) {
        self.remaining_capture_time = self.remaining_capture_time.saturating_sub(elapsed);
    }

    fn charge_match(&mut self, elapsed: Duration) -> bool {
        if elapsed >= self.remaining_match_time {
            self.remaining_match_time = Duration::ZERO;
            self.capped = true;
            false
        } else {
            self.remaining_match_time -= elapsed;
            true
        }
    }

    fn cap(&mut self) {
        self.capped = true;
    }
}

#[tool_router(router = inspect_router, vis = "pub(super)")]
impl TmuxTools {
    /// List every session on the server.
    #[tool(
        description = "List every tmux session on the server.",
        title = "List Sessions",
        meta = crate::capability_meta!(Inspect, None, [Observe], [TmuxMetadata], true, true, {})
    )]
    pub async fn list_sessions(&self) -> Result<Json<Sessions>, ToolError> {
        let sessions = self.server.sessions().await.map_err(|e| tmux_error(&e))?;
        let foreign_attached = self.foreign_attached_sessions().await;
        Ok(Json(Self::render_sessions(
            &sessions,
            foreign_attached.as_ref(),
        )))
    }

    /// List every window on the server, one row per session link.
    #[tool(
        description = "List every window on the server. A window linked into several sessions \
                       appears once per link, so an id can repeat with a different session_id.",
        title = "List Windows",
        meta = crate::capability_meta!(Inspect, None, [Observe], [TmuxMetadata], true, true, {})
    )]
    pub async fn list_windows(&self) -> Result<Json<Windows>, ToolError> {
        let windows = self.server.windows().await.map_err(|e| tmux_error(&e))?;
        Ok(Json(Self::render_windows(&windows)))
    }

    /// List every pane on the server.
    #[tool(
        description = "List every pane on the server.",
        title = "List Panes",
        meta = crate::capability_meta!(Inspect, None, [Observe], [TmuxMetadata], true, true, {}; always_load)
    )]
    pub async fn list_panes(&self) -> Result<Json<Panes>, ToolError> {
        let panes = self.server.panes().await.map_err(|e| tmux_error(&e))?;

        Ok(Json(self.render_panes(&panes)))
    }

    /// Report the whole hierarchy in one call.
    #[tool(
        name = "get_server_info",
        description = "Report every session with its windows and panes, in one call. \
                       Prefer this over calling the three listing tools separately: \
                       it costs tmux four commands rather than one per object.",
        title = "Describe Server",
        meta = crate::capability_meta!(Inspect, None, [Observe], [TmuxMetadata], true, true, {}; always_load)
    )]
    pub async fn describe(&self) -> Result<Json<Tree>, ToolError> {
        let tree = self.server.hierarchy().await.map_err(|e| tmux_error(&e))?;
        let foreign_attached = self.foreign_attached_sessions().await;
        let sessions: Vec<_> = tree
            .iter()
            .map(|branch| Branch {
                id: branch.session.id().to_string(),
                name: lossy(branch.session.name()),
                attached: foreign_attached.as_ref().map_or_else(
                    || branch.session.is_attached(),
                    |set| set.contains(&branch.session.id().to_string()),
                ),
                windows: branch
                    .windows
                    .iter()
                    .map(|built| BranchWindow {
                        id: built.window.id().to_string(),
                        index: built.window.index(),
                        name: lossy(built.window.name()),
                        active: built.window.is_active(),
                        linked: built.window.is_linked(),
                        panes: built
                            .panes
                            .iter()
                            .map(|pane| BranchPane {
                                id: pane.id().to_string(),
                                command: lossy_optional(pane.current_command()),
                                active: pane.is_active(),
                            })
                            .collect(),
                    })
                    .collect(),
            })
            .collect();

        Ok(Json(Tree { sessions }))
    }

    /// Read one pane's contents.
    #[tool(
        description = "Read a pane's contents. Reads the visible screen by default; set history \
                       to reach output that has scrolled off, or give a start and end line. \
                       Set last_command to get only what the last command printed, which is \
                       usually what you want and is far shorter -- it needs tmux 3.7 and a \
                       shell that marks its prompts, and says so when it cannot.",
        title = "Read Pane Contents",
        meta = crate::capability_meta!(Inspect, None, [Observe], [TmuxMetadata, TerminalContent], true, true, {
            "pane" => [TmuxLookup],
            "history" => [None],
            "last_command" => [None],
            "start" => [TmuxState],
            "end" => [TmuxState]
        })
    )]
    pub async fn capture_pane(
        &self,
        Parameters(CapturePaneArgs {
            pane,
            history,
            last_command,
            start,
            end,
        }): Parameters<CapturePaneArgs>,
    ) -> Result<Json<Capture>, ToolError> {
        if last_command {
            return self.capture_last_command(&pane).await;
        }

        let mut options = if history {
            CaptureOptions::history()
        } else {
            CaptureOptions::visible()
        };
        if let Some(start) = start {
            options = options.start(start);
        }
        if let Some(end) = end {
            options = options.end(end);
        }

        let pane = self.find_pane(&pane).await?;
        let lines = pane
            .capture_with(options)
            .await
            .map_err(|e| tmux_error(&e))?;

        let rendered: Vec<String> = lines
            .iter()
            .map(|line| line.to_string_lossy().into_owned())
            .collect();

        Ok(Json(Capture {
            pane: pane.id().to_string(),
            lines: rendered.len(),
            text: rendered.join("\n"),
            marks: Marks::NotAsked,
        }))
    }

    /// Report pane state and bounded content in one answer.
    #[tool(
        description = "Read pane content with cursor position, mode state, and scroll \
                       position in one reply. The state query and capture are separate, \
                       so the result is not atomic. Prefer this over capture_pane when \
                       you need to reason about where the pane is rather than only what \
                       it says -- a cursor at column zero on a fresh line is a shell \
                       waiting, and a pane in a mode may route keys to tmux instead of \
                       the workload.",
        title = "Snapshot Pane State",
        meta = crate::capability_meta!(Inspect, None, [Observe], [TmuxMetadata, TerminalContent], true, true, {
            "pane" => [TmuxLookup],
            "max_lines" => [None],
            "history" => [None]
        }; always_load)
    )]
    pub async fn snapshot_pane(
        &self,
        Parameters(SnapshotArgs {
            pane,
            max_lines,
            history,
        }): Parameters<SnapshotArgs>,
    ) -> Result<Json<Snapshot>, ToolError> {
        let target = self.find_pane(&pane).await?;

        // One format query for the state a listing does not carry.
        let reading = self
            .server
            .cmd(
                Command::new("display-message")
                    .arg("-p")
                    .arg("-t")
                    .arg(target.id().to_string())
                    .arg(format!(
                        "#{{cursor_x}}{SEPARATOR}#{{cursor_y}}{SEPARATOR}\
                         #{{pane_mode}}{SEPARATOR}#{{scroll_position}}"
                    )),
            )
            .await
            .map_err(|e| tmux_error(&e))?;
        let reading = reading.stdout_lossy();
        let mut fields = reading.trim_end_matches('\n').split(SEPARATOR);
        let cursor_x = fields.next().and_then(|field| field.parse::<u32>().ok());
        let cursor_y = fields.next().and_then(|field| field.parse::<u32>().ok());
        // tmux reports these empty for a pane that is not in a mode, which is
        // the ordinary case and not a failure to read them.
        let mode = fields.next().filter(|field| !field.is_empty());
        let scroll = fields.next().and_then(|field| field.parse::<i32>().ok());

        let options = if history {
            CaptureOptions::history()
        } else {
            CaptureOptions::visible()
        };
        let lines = target
            .capture_with(options)
            .await
            .map_err(|e| tmux_error(&e))?;
        let kept = max_lines.unwrap_or(lines.len()).min(lines.len());
        let dropped = lines.len() - kept;
        let content = lines
            .iter()
            .skip(dropped)
            .map(|line| line.to_string_lossy().into_owned())
            .collect::<Vec<_>>()
            .join("\n");

        let socket = self.socket();
        Ok(Json(Snapshot {
            pane: self.pane_view(&target, socket),
            width: target.width(),
            height: target.height(),
            cursor_x,
            cursor_y,
            in_mode: target.is_in_mode(),
            mode: mode.map(ToOwned::to_owned),
            scroll_position: scroll,
            dead: target.is_dead(),
            content,
            lines: kept,
            // Saying what was dropped is the difference between a short pane
            // and a long one the caller asked to see the end of.
            dropped,
        }))
    }

    /// Find which panes are showing something.
    #[tool(
        description = "Search what panes are displaying with Rust's linear-time regex engine. \
                       Accept at most 4,096 pattern bytes; search at most 64 panes, 8,192 lines, \
                       and 1 MiB; spend at most 250 ms matching and five seconds capturing. \
                       Report the pane and line of \
                       every match. Use this to find where something is -- which pane has \
                       the failing test, which one printed the error -- instead of capturing \
                       panes one at a time. Searches the visible screen by default; set \
                       history to include scrollback.",
        title = "Search Pane Contents",
        meta = crate::capability_meta!(Inspect, None, [Observe], [TmuxMetadata, TerminalContent], true, true, {
            "pattern" => [Regex],
            "regex" => [None],
            "match_case" => [None],
            "history" => [None],
            "session" => [TmuxLookup],
            "window" => [TmuxLookup]
        })
    )]
    pub async fn search_panes(
        &self,
        Parameters(SearchPanesArgs {
            pattern,
            regex,
            match_case,
            history,
            session,
            window,
        }): Parameters<SearchPanesArgs>,
    ) -> Result<Json<Matches>, ToolError> {
        let patterns = Patterns::compile(std::slice::from_ref(&pattern), regex, match_case)
            .map_err(|(source, reason)| {
                bad_input(format!("pattern {source} is invalid: {reason}"))
            })?;

        // Narrowed with tmux's own scoping first, so searching one window does
        // not read every pane on the server.
        let panes = match (session.as_deref(), window.as_deref()) {
            (_, Some(window)) => self.find_window(window).await?.panes().await,
            (Some(session), None) => self.find_session(session).await?.panes().await,
            (None, None) => self.server.panes().await,
        };
        let panes = panes.map_err(|e| tmux_error(&e))?;

        let options = if history {
            CaptureOptions::history()
        } else {
            CaptureOptions::visible()
        };
        let mut found: Vec<MatchView> = Vec::new();
        let mut budget = SearchBudget::new();
        let mut panes_searched = 0;
        'panes: for pane in &panes {
            if !budget.begin_pane() {
                break;
            }
            let Some(capture_time) = budget.capture_time() else {
                break;
            };
            // A pane that cannot be read is not a reason to abandon the
            // search: it is usually one that closed while this ran.
            let capture_started = Instant::now();
            let captured = tokio::time::timeout(capture_time, pane.capture_with(options)).await;
            budget.charge_capture(capture_started.elapsed());
            let lines = match captured {
                Ok(Ok(lines)) => lines,
                Ok(Err(_)) => continue,
                Err(_) => {
                    budget.cap();
                    break;
                }
            };
            panes_searched += 1;
            if found.len() >= SEARCH_MATCHES {
                // Reading the remaining panes could not change the answer, and
                // each one costs a capture.
                budget.capped = true;
                break;
            }
            for (number, line) in lines.iter().enumerate() {
                if found.len() >= SEARCH_MATCHES {
                    budget.capped = true;
                    break 'panes;
                }
                if !budget.take(line.as_bytes().len()) {
                    break 'panes;
                }
                let match_started = Instant::now();
                let matched = patterns.first_match(line.as_bytes()).is_some();
                if !budget.charge_match(match_started.elapsed()) {
                    break 'panes;
                }
                if matched {
                    found.push(MatchView {
                        pane: pane.id().to_string(),
                        window_id: pane.window_id().to_string(),
                        line: number,
                        text: line.to_string_lossy().into_owned(),
                    });
                }
            }
        }

        Ok(Json(Matches {
            // Saying the ceiling was reached is the difference between "that
            // is all of them" and "that is all you are getting".
            capped: budget.capped || found.len() >= SEARCH_MATCHES,
            matches: found,
            panes_searched,
        }))
    }

    /// Read a tmux option.
    #[tool(
        description = "Read a tmux option, such as history-limit or a user option like \
                       @theme. Name the scope the option lives in; global-session is what \
                       tmux uses when a command names no target.",
        title = "Read tmux Option",
        meta = crate::capability_meta!(
            Inspect, None,
            effects = [Observe],
            outputs = [TmuxMetadata, ConfiguredCommand],
            secrets = true,
            untrusted = true,
            sinks = {
                "name" => [TmuxLookup, TmuxFormat],
                "scope" => [None],
                "target" => [TmuxLookup]
            },
            literalized = ["name"],
            nested = [],
            self_bounded = false,
            always_load = false,
        )
    )]
    pub async fn show_option(
        &self,
        Parameters(OptionArgs {
            name,
            scope,
            target,
            ..
        }): Parameters<OptionArgs>,
    ) -> Result<Json<OptionValue>, ToolError> {
        let scope = self
            .option_scope(scope.as_deref(), target.as_deref())
            .await?;
        let value = match scope {
            OptionScope::Server => self.server.typed_option(&name).await,
            OptionScope::GlobalSession => self.server.typed_global_option(&name).await,
            OptionScope::GlobalWindow => self.server.typed_global_window_option(&name).await,
            OptionScope::Session(session) => session.typed_option(&name).await,
            OptionScope::Window(window) => window.typed_option(&name).await,
            OptionScope::Pane(pane) => pane.typed_option(&name).await,
        }
        .map_err(|e| tmux_error(&e))?;

        Ok(Json(OptionValue {
            name,
            // Absent and empty are different answers: tmux reports no value
            // for an option that has never been set at that scope.
            value: value.map(TmuxText::from).as_ref().map(lossy),
        }))
    }

    /// Read the names in a tmux environment, and the values the operator allowed.
    #[tool(
        description = "List the variables tmux hands to processes it starts, for the server \
                       or for one session, and whether each is set or marked for removal. \
                       Values are withheld: a tmux server inherits the environment of the \
                       shell that started it, tokens and keys included. A value is returned \
                       only for a name the operator listed in LIBTMUX_ENVIRONMENT_VALUES at \
                       startup, and is then returned in clear. This is not the environment of \
                       anything already running: a pane started before a change keeps what it \
                       was given.",
        title = "Show tmux Environment",
        meta = crate::capability_meta!(Inspect, None, [Observe], [ProcessEnvironment], true, true, {
            "session" => [TmuxLookup]
        })
    )]
    pub async fn show_environment(
        &self,
        Parameters(ShowEnvironmentArgs { session }): Parameters<ShowEnvironmentArgs>,
    ) -> Result<Json<Environment>, ToolError> {
        let entries = match session.as_deref() {
            Some(name) => self.find_session(name).await?.environment_all().await,
            None => self.server.environment_all().await,
        }
        .map_err(|e| tmux_error(&e))?;

        Ok(Json(Environment {
            entries: entries
                .into_iter()
                .map(|(name, entry)| match entry {
                    libtmux::EnvironmentEntry::Set(value) => {
                        let allowed = self.environment_values.contains(&name);
                        EnvironmentEntry {
                            name,
                            state: EnvironmentState::Set,
                            value: allowed.then(|| lossy(&value)),
                            withheld: !allowed,
                        }
                    }
                    libtmux::EnvironmentEntry::Removed => EnvironmentEntry {
                        name,
                        state: EnvironmentState::Removed,
                        value: None,
                        withheld: false,
                    },
                })
                .collect(),
            session,
        }))
    }

    /// Read the hooks tmux runs on its own events.
    #[tool(
        description = "List the hooks tmux runs when something happens on the server, such as \
                       a pane exiting. This tool does not set hooks. Hooks set through another \
                       path remain in their server or session until unset; configuration files \
                       persist them across server restarts. Reach for this when tmux does \
                       something no tool here asked for.",
        title = "Show tmux Hooks",
        meta = crate::capability_meta!(Inspect, None, [Observe], [ConfiguredCommand], true, true, {
            "session" => [TmuxLookup]
        })
    )]
    pub async fn show_hooks(
        &self,
        Parameters(ShowHooksArgs { session }): Parameters<ShowHooksArgs>,
    ) -> Result<Json<Hooks>, ToolError> {
        let found = match session.as_deref() {
            Some(name) => self.find_session(name).await?.hooks().await,
            None => self.server.hooks().await,
        }
        .map_err(|e| tmux_error(&e))?;

        let mut hooks = Vec::new();
        for (name, indexed) in found {
            for (index, command) in &indexed {
                hooks.push(Hook {
                    name: name.clone(),
                    // tmux numbers an array hook and leaves a single one bare.
                    index: (indexed.len() > 1).then_some(*index),
                    command: lossy(command),
                });
            }
        }

        Ok(Json(Hooks { hooks }))
    }
}

#[cfg(test)]
mod tests {
    use super::SearchBudget;

    #[test]
    fn search_budget_refuses_bytes_beyond_the_limit() {
        let mut budget = SearchBudget::new();
        budget.remaining_bytes = 3;

        assert!(budget.take(2));
        assert!(!budget.take(2));
        assert!(budget.capped);
    }

    #[test]
    fn search_budget_counts_zero_byte_lines_as_work() {
        let mut budget = SearchBudget::new();

        for _ in 0..8192 {
            assert!(budget.take(0));
        }
        assert!(!budget.take(0));
        assert!(budget.capped);
    }
}

crates/tmux-mcp/src/tools/mod.rs.content:
mod contract;
mod control;
pub(crate) mod error;
mod inspect;
mod observe;
mod pane_input;

use std::collections::BTreeSet;
use std::path::Path;
use std::time::Duration;

use libtmux::{CaptureOptions, TmuxText};
use rmcp::handler::server::wrapper::Json;
use rmcp::model::ErrorData;

use crate::caller::Relation;
use crate::{
    Capture, Marks, PaneView, Panes, SessionView, Sessions, TmuxTools, WindowView, Windows,
};

use error::{ToolError, bad_input, object_gone, tmux_error};

/// Render tmux bytes for a protocol that requires valid UTF-8.
///
/// tmux permits names and titles that are not UTF-8. JSON cannot carry those
/// bytes, so they are replaced rather than dropping the whole response.
fn lossy(value: &TmuxText) -> String {
    value.to_string_lossy().into_owned()
}

/// The same, for a field tmux may genuinely not report.
fn lossy_optional(value: Option<&TmuxText>) -> Option<String> {
    value.map(lossy)
}

/// Which tmux object an option belongs to.
///
/// Boxed because a `Session`, `Window` and `Pane` each carry their own
/// snapshot, and the enum is a short-lived dispatch rather than something
/// worth sizing to its largest arm.
enum OptionScope {
    /// The server's own options.
    Server,
    /// The session options a new session inherits.
    GlobalSession,
    /// The window options a new window inherits.
    GlobalWindow,
    /// One session's options.
    Session(Box<libtmux::Session>),
    /// One window's options.
    Window(Box<libtmux::Window>),
    /// One pane's options.
    Pane(Box<libtmux::Pane>),
}

pub(super) fn router() -> rmcp::handler::server::router::tool::ToolRouter<TmuxTools> {
    TmuxTools::inspect_router()
        + TmuxTools::control_router()
        + TmuxTools::contract_router()
        + TmuxTools::observe_router()
}

impl TmuxTools {
    /// Describe sessions, shared by the tool and the `tmux://` resource so the
    /// two cannot drift into different accounts of the same session.
    ///
    /// `foreign_attached` overrides `Session::is_attached` when it is
    /// `Some`: see [`Self::foreign_attached_sessions`].
    pub(super) fn render_sessions(
        sessions: &[libtmux::Session],
        foreign_attached: Option<&BTreeSet<String>>,
    ) -> Sessions {
        Sessions {
            sessions: sessions
                .iter()
                .map(|session| {
                    let id = session.id().to_string();
                    let attached = foreign_attached
                        .map_or_else(|| session.is_attached(), |set| set.contains(&id));
                    SessionView {
                        id,
                        name: lossy(session.name()),
                        windows: session.window_count(),
                        attached,
                    }
                })
                .collect(),
        }
    }

    /// The sessions with a client attached that this process did not open
    /// for its own observation.
    ///
    /// While `wait_for_text`, `stream_output`, or any other control
    /// connection this server opens is live, tmux counts it as an attached
    /// client the same as a human's terminal: `Session::is_attached` alone
    /// cannot tell the two apart. `Server::owns_control_client` resolves
    /// each client this reads from `list-clients` by pid, so a session
    /// reads as attached only when something else is there too.
    ///
    /// `None` when the listing itself could not be read: an empty server
    /// reports `no current target` for a server-wide listing, and every
    /// caller here falls back to `Session::is_attached` rather than
    /// answering `false` for a session that may well be attached.
    pub(super) async fn foreign_attached_sessions(&self) -> Option<BTreeSet<String>> {
        let result = self
            .server
            .cmd(
                libtmux::Command::new("list-clients")
                    .arg("-F")
                    .arg("#{session_id} #{client_pid}"),
            )
            .await
            .ok()?;
        if !result.success() {
            return None;
        }

        let mut sessions = BTreeSet::new();
        for line in result.stdout_lossy().lines() {
            let mut fields = line.split(' ');
            let (Some(session), Some(pid)) = (fields.next(), fields.next()) else {
                continue;
            };
            let Ok(pid) = pid.parse::<u32>() else {
                continue;
            };
            if !self.server.owns_control_client(pid) {
                sessions.insert(session.to_owned());
            }
        }
        Some(sessions)
    }

    /// Read what the last command in a pane printed.
    ///
    /// tmux records where a prompt and its output begin from the OSC 133
    /// sequences a shell emits. Where those marks exist this is exact; where
    /// they do not, the whole screen comes back with `marks` saying why, so a
    /// caller reads a field rather than guessing from a suspiciously long
    /// answer.
    pub(super) async fn capture_last_command(
        &self,
        pane: &str,
    ) -> Result<Json<Capture>, ToolError> {
        let target = self.find_pane(pane).await?;
        // The daemon runs the capture, so its version decides the flags; the
        // client executable's can differ.
        let supported = self
            .server
            .daemon_version()
            .await
            .is_ok_and(|version| version.has_behavior(&libtmux::since::CAPTURE_LINE_FLAGS));

        let (rendered, marks) = if supported {
            let lines = target
                .capture_lines(CaptureOptions::history())
                .await
                .map_err(|e| tmux_error(&e))?;

            // The last run begins at the last line marked as output, and ends
            // where the next prompt begins -- which for the last command is
            // the end of what tmux holds.
            match lines.iter().rposition(|line| line.starts_output) {
                Some(from) => {
                    // Searched past the output's own line: a shell that emits
                    // both marks before printing anything puts them on one
                    // line, and that prompt cannot delimit its own output.
                    let to = lines[from + 1..]
                        .iter()
                        .position(|line| line.starts_prompt)
                        .map_or(lines.len(), |offset| from + 1 + offset);
                    (
                        lines[from..to]
                            .iter()
                            .map(|line| line.text.to_string_lossy().into_owned())
                            .collect::<Vec<_>>(),
                        Marks::Present,
                    )
                }
                // Falling back to the history would answer a request for one
                // command's output with everything the pane ever printed,
                // which is the most expensive answer available. The visible
                // screen is the bounded approximation.
                None => (
                    target
                        .capture_with(CaptureOptions::visible())
                        .await
                        .map_err(|e| tmux_error(&e))?
                        .iter()
                        .map(|line| line.to_string_lossy().into_owned())
                        .collect(),
                    Marks::Absent,
                ),
            }
        } else {
            let lines = target
                .capture_with(CaptureOptions::visible())
                .await
                .map_err(|e| tmux_error(&e))?;
            (
                lines
                    .iter()
                    .map(|line| line.to_string_lossy().into_owned())
                    .collect(),
                Marks::Unsupported,
            )
        };

        Ok(Json(Capture {
            pane: target.id().to_string(),
            lines: rendered.len(),
            text: rendered.join("\n"),
            marks,
        }))
    }

    /// Render one window as the protocol sees it.
    pub(super) fn one_window(window: &libtmux::Window) -> WindowView {
        WindowView {
            id: window.id().to_string(),
            session_id: window.session_id().to_string(),
            index: window.index(),
            name: lossy(window.name()),
            panes: window.pane_count(),
            active: window.is_active(),
            linked: window.is_linked(),
        }
    }

    /// Render windows as the protocol sees them.
    pub(super) fn render_windows(windows: &[libtmux::Window]) -> Windows {
        let windows: Vec<_> = windows.iter().map(Self::one_window).collect();

        Windows { windows }
    }

    /// Resolve the object an option belongs to.
    async fn option_scope(
        &self,
        scope: Option<&str>,
        target: Option<&str>,
    ) -> Result<OptionScope, ToolError> {
        let needs = |what: &str| bad_input(format!("scope {what} needs a target id"));

        match scope {
            Some("server") => Ok(OptionScope::Server),
            None | Some("global-session") => Ok(OptionScope::GlobalSession),
            Some("global-window") => Ok(OptionScope::GlobalWindow),
            Some("session") => Ok(OptionScope::Session(Box::new(
                self.find_session(target.ok_or_else(|| needs("session"))?)
                    .await?,
            ))),
            Some("window") => Ok(OptionScope::Window(Box::new(
                self.find_window(target.ok_or_else(|| needs("window"))?)
                    .await?,
            ))),
            Some("pane") => Ok(OptionScope::Pane(Box::new(
                self.find_pane(target.ok_or_else(|| needs("pane"))?).await?,
            ))),
            Some(unknown) => Err(bad_input(format!(
                "scope must be server, global-session, global-window, session, window, \
                     or pane, not {unknown}"
            ))),
        }
    }

    /// How long a blocking tool may hold the caller's turn.
    ///
    /// An MCP call blocks the agent that made it, so an unbounded wait costs a
    /// whole turn with nothing to show. The ceiling is generous enough for a
    /// slow build and short enough that a wedged wait is an annoyance.
    pub(super) fn budget(seconds: Option<u64>) -> Duration {
        Duration::from_secs(seconds.unwrap_or(30).clamp(1, 600))
    }

    /// Render panes as the protocol sees them, saying which one is our own.
    pub(super) fn render_panes(&self, panes: &[libtmux::Pane]) -> Panes {
        let socket = self.socket();
        let panes: Vec<_> = panes
            .iter()
            .map(|pane| self.pane_view(pane, socket))
            .collect();

        Panes { panes }
    }

    /// Describe one pane, including where it stands relative to this process.
    pub(super) fn pane_view(&self, pane: &libtmux::Pane, socket: Option<&Path>) -> PaneView {
        let id = pane.id().to_string();
        PaneView {
            caller: self
                .caller
                .as_ref()
                .map_or(Relation::Unknown, |caller| caller.relation_to(&id, socket)),
            id,
            window_id: pane.window_id().to_string(),
            command: lossy_optional(pane.current_command()),
            path: lossy_optional(pane.current_path()),
            active: pane.is_active(),
        }
    }

    /// The socket path this process connects through.
    ///
    /// Taken from this crate's configuration rather than from
    /// `#{socket_path}`, for the reasons `pane_input_endpoint` records: tmux
    /// stores a non-printable byte in the path as an octal escape and
    /// releases disagree about it, and reading the answer back as lossy UTF-8
    /// replaced any non-UTF-8 byte regardless of version. Both produced a
    /// path that matched nothing, which for a caller comparison means failing
    /// to recognize the caller's own pane.
    ///
    /// Resolved once. Two calls racing compute the same answer, so the loser
    /// discarding its own is harmless.
    pub(super) fn socket(&self) -> Option<&Path> {
        self.socket
            .get_or_init(|| Some(self.server.socket_path().to_path_buf()))
            .as_deref()
    }

    /// The pane protected as the inherited caller on this server.
    ///
    /// A returned pane has been resolved in the caller's claimed session on
    /// the selected daemon. Malformed or stale context refuses the operation.
    pub(super) async fn protected_pane(&self) -> Result<Option<&str>, ToolError> {
        if self.caller.is_none() {
            return Ok(None);
        }
        let generation = self.server.generation().await.map_err(|e| tmux_error(&e))?;
        let panes = self.server.panes().await.map_err(|e| tmux_error(&e))?;
        let socket = self.socket().ok_or_else(|| {
            Self::caller_context_refusal("tmux did not report its selected socket")
        })?;
        self.server
            .require_generation(generation)
            .await
            .map_err(|e| tmux_error(&e))?;
        self.caller_pane_for_snapshot(socket, generation, &panes)
    }

    pub(super) fn caller_pane_for_snapshot<'a>(
        &'a self,
        socket: &Path,
        generation: libtmux::ServerGeneration,
        panes: &[libtmux::Pane],
    ) -> Result<Option<&'a str>, ToolError> {
        let Some(caller) = self.caller.as_deref() else {
            return Ok(None);
        };
        caller
            .resolve_on(socket, generation, panes)
            .map_err(|detail| {
                Self::caller_context_refusal(&format!("inherited caller context is {detail}"))
            })
    }

    /// The tools this server offers after startup selection.
    #[must_use]
    pub fn offered(&self) -> Vec<rmcp::model::Tool> {
        self.tool_router.list_all()
    }

    /// The pane this process runs in, when tmux named a complete identity.
    ///
    /// Reported without checking it against the server, because this is for
    /// saying what the environment claimed rather than for deciding anything.
    #[must_use]
    pub fn caller_pane(&self) -> Option<&str> {
        self.caller.as_ref().and_then(|caller| caller.pane_id())
    }

    /// Whether the inherited caller context is set but malformed, which makes
    /// pane-input and teardown tools refuse every call.
    #[must_use]
    pub fn caller_is_malformed(&self) -> bool {
        self.caller
            .as_ref()
            .is_some_and(|caller| caller.is_malformed())
    }

    /// Classify a refusal that protects the pane this process talks through.
    pub(super) fn self_protection(message: String) -> ToolError {
        ErrorData::invalid_params(
            message,
            // Its own kind, because this is the server declining rather than
            // tmux: an agent that reads `refused` might reasonably try a
            // different argument, and no argument gets past this one.
            Some(serde_json::json!({
                "kind": "self_protection",
                "retryable": false,
                "stale": false,
            })),
        )
        .into()
    }

    fn caller_context_refusal(detail: &str) -> ToolError {
        Self::self_protection(format!(
            "refusing this operation because {detail}; restart the MCP outside tmux or with a complete current TMUX and TMUX_PANE context"
        ))
    }

    /// Refuse a command that may destroy the pane this process talks through.
    pub(super) fn self_harm(what: &str, own: &str) -> ToolError {
        Self::self_protection(format!(
            "refusing to kill this {what}: pane {own} matches this MCP server's inherited \
             caller context, so killing it may end this conversation. Run the command in \
             a terminal if that is what you meant."
        ))
    }

    /// Resolve a window id, reporting an unknown one as invalid input.
    ///
    /// The id is parsed before tmux sees it, which buys three things over
    /// scanning a full listing. tmux matches the id server-side and returns
    /// the one row. Text that is not an id at all is reported as bad input
    /// rather than as a window that went away, because an agent told "look
    /// again" will look again and `not-a-window` will still not be a window.
    /// And `@01` resolves, where a string comparison against the canonical
    /// `@1` called it missing.
    pub(super) async fn find_window(&self, id: &str) -> Result<libtmux::Window, ToolError> {
        let window: libtmux::WindowId = id.parse().map_err(|error: libtmux::IdParseError| {
            let sigil = error.expected_sigil();
            bad_input(format!(
                "{id} is not a window id: expected {sigil} followed by digits, as in {sigil}1"
            ))
        })?;

        self.server
            .window_by_id(&window)
            .await
            .map_err(|e| tmux_error(&e))?
            .ok_or_else(|| object_gone("window", id))
    }

    /// Resolve a pane id, reporting an unknown one as invalid input.
    ///
    /// Shares the reasoning on [`Self::find_window`].
    pub(super) async fn find_pane(&self, id: &str) -> Result<libtmux::Pane, ToolError> {
        let pane: libtmux::PaneId = id.parse().map_err(|error: libtmux::IdParseError| {
            let sigil = error.expected_sigil();
            bad_input(format!(
                "{id} is not a pane id: expected {sigil} followed by digits, as in {sigil}1"
            ))
        })?;

        self.server
            .pane_by_id(&pane)
            .await
            .map_err(|e| tmux_error(&e))?
            .ok_or_else(|| object_gone("pane", id))
    }

    /// Resolve a session by `$`-prefixed id or by name.
    ///
    /// An id is looked up as one, because the server's instructions tell an
    /// agent to prefer ids. Text that starts with `$` and is neither an id
    /// nor a session's name is invalid input, not a session that went away.
    pub(super) async fn find_session(&self, target: &str) -> Result<libtmux::Session, ToolError> {
        if target.starts_with('$')
            && let Ok(id) = target.parse::<libtmux::SessionId>()
        {
            return self
                .server
                .session_by_id(&id)
                .await
                .map_err(|e| tmux_error(&e))?
                .ok_or_else(|| object_gone("session", target));
        }
        let named = self
            .server
            .sessions()
            .await
            .map_err(|e| tmux_error(&e))?
            .into_iter()
            .find(|session| session.name() == target.as_bytes());
        match named {
            Some(session) => Ok(session),
            None if target.starts_with('$') => Err(bad_input(format!(
                "{target} is not a session id or name: an id is $ followed by digits, as in $1"
            ))),
            None => Err(object_gone("session", target)),
        }
    }
}

crates/tmux-mcp/src/tools/observe.rs.content:
use std::path::PathBuf;

use rmcp::handler::server::wrapper::{Json, Parameters};
use rmcp::model::ErrorData;
use rmcp::{tool, tool_router};

