#[derive(Clone, Eq, PartialEq)]
struct RunRoute {
    executable: PathBuf,
    endpoint: PathBuf,
    pane: String,
    generation: libtmux::ServerGeneration,
}

fn known_posix_shell(command: &libtmux::TmuxText) -> bool {
    let basename = command
        .as_bytes()
        .rsplit(|byte| *byte == b'/')
        .next()
        .unwrap_or_default();
    let basename = basename.strip_prefix(b"-").unwrap_or(basename);
    [
        b"ash".as_slice(),
        b"bash",
        b"dash",
        b"ksh",
        b"ksh93",
        b"mksh",
        b"pdksh",
        b"sh",
        b"zsh",
    ]
    .contains(&basename)
}

fn require_known_shell(
    plan: &PaneInputPlan,
    checkpoint: &str,
) -> Result<libtmux::TmuxText, ToolError> {
    let pane = plan.target.id();
    let Some(command) = plan
        .target
        .current_command()
        .filter(|command| known_posix_shell(command))
    else {
        return Err(bad_input(format!(
            "pane {pane} must run a known POSIX-compatible foreground shell at the {checkpoint} run checkpoint"
        )));
    };
    Ok(command.clone())
}

fn resolved_executable(server: &libtmux::Server) -> Result<PathBuf, ToolError> {
    server.resolved_tmux_executable().ok_or_else(|| {
        ErrorData::internal_error(
            "the configured tmux executable cannot be resolved from its captured launch context"
                .to_owned(),
            Some(serde_json::json!({
                "kind": "unreachable",
                "retryable": false,
                "stale": false,
            })),
        )
        .into()
    })
}

fn run_route(server: &libtmux::Server, plan: &PaneInputPlan) -> Result<RunRoute, ToolError> {
    let executable = resolved_executable(server)?;
    if !exec::route_is_terminal_safe(executable.as_os_str(), &plan.endpoint) {
        return Err(run_error(run_request::RunError::Frame));
    }
    Ok(RunRoute {
        executable,
        endpoint: plan.endpoint.clone(),
        pane: plan.target.id().to_string(),
        generation: plan.generation,
    })
}

/// Translate a request-owned run failure at the protocol boundary.
fn run_error(error: run_request::RunError) -> ToolError {
    match error {
        run_request::RunError::Tmux(error) => tmux_error(&error),
        run_request::RunError::DispatchUnknown(cause) => ErrorData::internal_error(
            format!(
                "tmux did not confirm whether it started the pane command: {cause}; inspect the pane \
                     before acting because the command may be running. Do not retry \
                     automatically. To interrupt, use pane-wide send_keys with keys=[\"C-c\"], \
                     which can discard unrelated queued input"
            ),
            Some(serde_json::json!({
                "kind": "dispatch_unknown",
                "retryable": false,
                "stale": false,
            })),
        )
        .into(),
        run_request::RunError::Guard(error) => error,
        run_request::RunError::Frame => ErrorData::internal_error(
            "run_shell_command could not prepare a secure completion frame; no pane input was sent"
                .to_owned(),
            Some(serde_json::json!({
                "kind": "unreachable",
                "retryable": false,
                "stale": false,
            })),
        )
        .into(),
    }
}

fn tail_error(error: TailError) -> ToolError {
    match error {
        TailError::Tmux(error) => tmux_error(&error),
        TailError::Snapshot { error, opened } => tail_snapshot_error(error, opened),
        TailError::SnapshotBusy { opened, limit } => {
            if opened {
                let mut boundary = EffectBoundary::new("capture_since");
                boundary.mark();
                boundary.local(
                    "the pane tail opened, but another baseline capture is already queued; inspect \
                     the pane before retrying",
                )
            } else {
                ErrorData::internal_error(
                    "another baseline capture is already queued; retry capture_since after it \
                     finishes"
                        .to_owned(),
                    Some(serde_json::json!({
                        "kind": "capacity",
                        "retryable": true,
                        "stale": false,
                        "resource": "tail_snapshot",
                        "capacity": limit,
                    })),
                )
                .into()
            }
        }
        TailError::ReaderStopped { opened } => {
            if opened {
                let mut boundary = EffectBoundary::new("capture_since");
                boundary.mark();
                boundary.local(
                    "the pane tail opened, but its reader stopped before the baseline completed; \
                     inspect the pane before retrying",
                )
            } else {
                ErrorData::internal_error(
                    "the retained pane tail reader stopped; retry capture_since to replace it"
                        .to_owned(),
                    Some(serde_json::json!({
                        "kind": "unreachable",
                        "retryable": true,
                        "stale": false,
                    })),
                )
                .into()
            }
        }
        TailError::OwnerUnavailable => ErrorData::internal_error(
            "capture cursor identity is unavailable".to_owned(),
            Some(serde_json::json!({
                "kind": "unreachable",
                "retryable": true,
                "stale": false,
            })),
        )
        .into(),
        TailError::OpeningAtCapacity { limit } => ErrorData::internal_error(
            "another pane tail is opening; retry capture_since after it finishes".to_owned(),
            Some(serde_json::json!({
                "kind": "capacity",
                "retryable": true,
                "stale": false,
                "resource": "tail_opening",
                "capacity": limit,
            })),
        )
        .into(),
    }
}

fn tail_snapshot_error(error: libtmux::Error, opened: bool) -> ToolError {
    let mut boundary = EffectBoundary::new("capture_since");
    if opened {
        boundary.mark();
    }
    boundary.error(error)
}

#[tool_router(router = observe_router, vis = "pub(super)")]
impl TmuxTools {
    /// Run a command in a pane and report how it went.
    #[tool(
        name = "run_shell_command",
        description = "Run a shell command in a pane, wait for it to finish, and report its \
                       exit status with retained output. This is the tool for \"run this \
                       and tell me if it worked\". Output is the pane's raw output stream, not \
                       the rendered screen. Output is a bounded tail; check truncated before \
                       treating it as complete. The shell prompt is not \
                       included, and a line redrawn in place repeats; capture_pane shows the \
                       screen. The command \
                       runs in a subshell, so cd and export do not persist and invalid syntax \
                       completes with a nonzero status. Valid inherited Bash and zsh ERR and \
                       DEBUG traps remain visible to the command while parent-shell traps and \
                       options remain unchanged. It requires one configured input \
                       recipient and observes its mode, liveness, input-off state, attended-client \
                       state, cohort, inherited-caller relation, known POSIX shell, and resolved \
                       route before watcher setup and again before dispatch. A process-wide \
                       endpoint-and-pane reservation blocks other MCP pane input until the \
                       completion marker or pane closure is proved. The resolved tmux executable \
                       and socket path must contain no ASCII terminal-control bytes. The \
                       reservation serializes this MCP's input, but tmux observations can still \
                       race with dispatch. The pane shell, tmux server, and configuration must be \
                       trusted. Reaching the deadline, cancelling, or an uncertain dispatch stops \
                       this request while its watcher keeps the reservation until completion is \
                       proved. To stop the command, send_keys with keys [\"C-c\"] alone passes \
                       the reservation, and the command reports completion when it ends; \
                       respawn_pane with kill_first replaces a program that ignores C-c and C-\\.",
        title = "Run Command In Pane",
        meta = crate::capability_meta!(Execute, PaneCommand, [Change], [TmuxMetadata, TerminalContent], true, true, {
            "pane" => [TmuxLookup],
            "command" => [PaneInput, ShellCommand],
            "seconds" => [None],
            "suppress_history" => [None]
        })
    )]
    pub async fn run_command(
        &self,
        Parameters(RunCommandArgs {
            pane,
            command,
            seconds,
            suppress_history,
        }): Parameters<RunCommandArgs>,
        cancelled: tokio_util::sync::CancellationToken,
        reporter: Reporter,
    ) -> Result<Json<RunView>, ToolError> {
        if command.as_bytes().contains(&0) {
            return Err(bad_input("command must not contain a NUL byte".to_owned()));
        }
        let configured_executable = resolved_executable(&self.server)?;
        if !exec::route_is_terminal_safe(
            configured_executable.as_os_str(),
            self.server.socket_path(),
        ) {
            return Err(run_error(run_request::RunError::Frame));
        }
        let initial = self
            .preflight_pane_input(
                &pane,
                PaneInputReach::Synchronized,
                MissingSource::CallerInput,
            )
            .await?;
        if initial.configured.len() != 1 {
            return Err(bad_input(format!(
                "pane {pane} has synchronized input enabled for {} panes; run_shell_command requires one configured recipient",
                initial.configured.len()
            )));
        }
        let foreground = require_known_shell(&initial, "initial")?;
        let route = run_route(&self.server, &initial)?;
        let lease = initial
            .reserve()
            .ok_or_else(|| active_run_error(&route.pane))?;
        let checkpoint_pane = initial.target.id().to_string();
        let expected_route = route.clone();
        let final_lease = lease.clone();
        let final_check = async {
            let final_plan = self
                .preflight_reserved_pane_input(
                    &checkpoint_pane,
                    PaneInputReach::Synchronized,
                    MissingSource::ObservedTransition,
                    &final_lease,
                )
                .await?;
            if final_plan.configured.len() != 1 {
                return Err(bad_input(format!(
                    "pane {checkpoint_pane} gained synchronized recipients between run checkpoints"
                )));
            }
            let final_foreground = require_known_shell(&final_plan, "final")?;
            if final_foreground != foreground {
                return Err(bad_input(format!(
                    "pane {checkpoint_pane} changed its POSIX-compatible foreground shell between run checkpoints"
                )));
            }
            if !initial.same_authority(&final_plan) {
                return Err(bad_input(format!(
                    "pane {checkpoint_pane} changed its configured input authority between run checkpoints"
                )));
            }
            let final_route = run_route(&self.server, &final_plan)?;
            if final_route != expected_route || !final_plan.owns(&final_lease) {
                return Err(bad_input(format!(
                    "pane {checkpoint_pane} changed its tmux route or active-run reservation between run checkpoints"
                )));
            }
            Ok(())
        };
        let view = Box::pin(reporting(
            reporter,
            "still running",
            run_request::run(
                &initial.target,
                &command,
                Self::budget(seconds),
                suppress_history,
                &cancelled,
                run_request::RunTransport {
                    server: &self.server,
                    generation: initial.generation,
                    executable: route.executable.as_os_str(),
                    endpoint: &route.endpoint,
                    shell: foreground.as_bytes(),
                    lease,
                    echoes: self.echoes.as_ref(),
                },
                final_check,
            ),
        ))
        .await
        .map_err(run_error)?;

        Ok(Json(view))
    }

    /// Wait until a pane writes something a caller is looking for.
    #[tool(
        description = "Wait until a pane writes matching text. On tmux 3.7 or newer it reads the \
                       pane's live output stream, so text that scrolls past between checks is \
                       still seen, and the returned text is that raw stream, not the rendered \
                       screen: a line redrawn in place repeats. Below 3.7 it polls the \
                       visible screen about every 120 ms and misses text that appears and \
                       scrolls off between two reads. capture_pane shows the screen. Prefer \
                       run_shell_command for commands you are sending yourself: it reports an \
                       exit status instead of guessing from output. Use this for output you did \
                       not author, such as a server logging that it is ready. A line this server \
                       itself types and submits -- with send_keys, paste_text, or \
                       run_shell_command's own dispatch -- is discounted from a match for a \
                       short time afterward, so waiting for text you just sent does not match \
                       its own echo; output that happens to repeat the same words still does. A \
                       submitted line that wrapped across terminal rows is discounted as one line. \
                       A pattern still on the row being typed into, not yet \
                       submitted, reports outcome pending instead of matched, and one already on \
                       a completed row before this call attached reports present_at_entry. A \
                       pane or server that ends reports pane_closed; an observer stream that \
                       drops while the pane lives reports stream_lost. \
                       On 3.7 or newer, waiting owns an observer client until the wait \
                       ends. Each list accepts at most 32 patterns, each at most 4,096 \
                       bytes, using Rust's linear-time regex engine.",
        title = "Wait For Pane Text",
        meta = crate::capability_meta!(
            Inspect, None,
            effects = [Observe],
            outputs = [TmuxMetadata, TerminalContent],
            secrets = true,
            untrusted = true,
            sinks = {
                "pane" => [TmuxLookup],
                "patterns" => [Regex],
                "stop" => [Regex],
                "regex" => [None],
                "match_case" => [None],
                "seconds" => [None]
            },
            literalized = [],
            nested = [],
            self_bounded = true,
            always_load = false,
        )
    )]
    pub async fn wait_for_text(
        &self,
        Parameters(WaitForTextArgs {
            pane,
            patterns,
            stop,
            regex,
            match_case,
            seconds,
        }): Parameters<WaitForTextArgs>,
        cancelled: tokio_util::sync::CancellationToken,
        reporter: Reporter,
    ) -> Result<Json<WaitView>, ToolError> {
        let compile = |sources: Vec<String>| {
            Patterns::compile(&sources, regex, match_case).map_err(|(source, reason)| {
                bad_input(format!("pattern {source} is invalid: {reason}"))
            })
        };
        let wanted = compile(patterns.unwrap_or_default())?;
        let stops = compile(stop.unwrap_or_default())?;

        let target = self.find_pane(&pane).await?;
        // Best-effort: a generation this crate cannot read is not a reason
        // to refuse the wait, only to skip discounting this server's own
        // recent echo on it.
        let key = self.server.generation().await.ok().and_then(|generation| {
            crate::echo::EchoKey::new(generation, self.server.socket_path(), target.id().as_ref())
        });
        let view = reporting(
            reporter,
            "still watching for the pattern",
            exec::wait_for_text(
                &self.server,
                &target,
                &wanted,
                &stops,
                Self::budget(seconds),
                &cancelled,
                exec::EchoContext {
                    echoes: &self.echoes,
                    key: key.as_ref(),
                },
            ),
        )
        .await
        .map_err(|e| tmux_error(&e))?;

        Ok(Json(view))
    }

    /// Report what a pane has written since the last look.
    #[tool(
        description = "Read what a pane wrote since the previous call. The first call, with no \
                       cursor, starts watching and returns a cursor; later calls pass it back \
                       and receive only what is new, as the raw output stream, not the rendered \
                       screen: a line redrawn in place repeats; capture_pane shows the screen. \
                       Use this to follow a pane over several \
                       turns without re-reading the whole screen. The answer says missed=true \
                       if the cursor no longer names retained output, including when the pane \
                       outran the buffer, its live tail was evicted, or the server restarted. \
                       Starting a tail owns a retained observer until the tail is evicted or \
                       the server stops.",
        title = "Read New Pane Output",
        meta = crate::capability_meta!(Inspect, None, [Observe], [TmuxMetadata, TerminalContent], true, true, {
            "pane" => [TmuxLookup],
            "cursor" => [None]
        })
    )]
    pub async fn capture_since(
        &self,
        Parameters(CaptureSinceArgs { pane, cursor }): Parameters<CaptureSinceArgs>,
    ) -> Result<Json<Since>, ToolError> {
        let target = self.find_pane(&pane).await?;
        let cursor = cursor
            .as_deref()
            .map(Cursor::decode)
            .transpose()
            .map_err(|text| bad_input(format!("{text} is not a cursor this server issued")))?;
        if let Some(cursor) = &cursor
            && cursor.pane() != target.id().to_string()
        {
            return Err(bad_input(format!(
                "that cursor belongs to pane {}, not {pane}",
                cursor.pane()
            )));
        }

        let first = cursor.is_none();
        let since = self
            .tails
            .read(&target, cursor.as_ref())
            .await
            .map_err(tail_error)?;

        Ok(Json(Since {
            pane: target.id().to_string(),
            text: since.text,
            cursor: since.cursor.encode(),
            missed: since.missed,
            closed: since.closed,
            // The first answer is the screen as it stands; every later one is
            // what the pane wrote since the cursor.
            first,
        }))
    }

    /// Wait for a `wait-for` channel to be signalled.
    #[tool(
        description = "Block until something signals a tmux wait-for channel. A pending \
                       signal is consumed. Pair this with a shell command that ends in \
                       `tmux wait-for -S <channel>` to synchronise with work this server \
                       did not start.",
        title = "Wait For Channel",
        meta = crate::capability_meta!(Manage, None, [Change], [TmuxMetadata], true, true, {
            "channel" => [TmuxState],
            "seconds" => [None]
        })
    )]
    pub async fn wait_for_channel(
        &self,
        Parameters(ChannelArgs { channel, seconds }): Parameters<ChannelArgs>,
    ) -> Result<Json<ChannelWait>, ToolError> {
        // libtmux caps this at its own command timeout and reports running
        // out of time as an outcome rather than an error, which is the shape
        // this tool wants: the budget stays a request, and a deadline stays
        // distinct from a failure to reach tmux.
        let outcome = match self
            .server
            .wait_for_channel(channel.as_str(), Self::budget(seconds))
            .await
        {
            Ok(libtmux::ChannelWait::Signalled) => "signalled",
            Ok(libtmux::ChannelWait::TimedOut) => "deadline",
            // The schema promises one of those two words. `ChannelWait` may
            // grow a third, and answering with the nearest existing label
            // would report something that did not happen.
            Ok(_) => {
                return Err(ErrorData::internal_error(
                    "tmux reported a wait outcome this server does not know".to_owned(),
                    None,
                )
                .into());
            }
            Err(error) => return Err(tmux_error(&error)),
        };

        Ok(Json(ChannelWait {
            channel,
            outcome: outcome.to_owned(),
        }))
    }
}

#[cfg(test)]
mod tests {
    use std::time::Duration;

    use libtmux::test::TestServer;
    use tokio_util::sync::CancellationToken;

    use super::*;

    async fn client_count(server: &libtmux::Server) -> usize {
        server.clients().await.map_or(0, |clients| clients.len())
    }

    #[test]
    fn run_shell_allowlist_is_exact() {
        for shell in [
            "ash",
            "bash",
            "dash",
            "ksh",
            "ksh93",
            "mksh",
            "pdksh",
            "sh",
            "zsh",
            "/bin/bash",
            "-zsh",
        ] {
            assert!(
                known_posix_shell(&libtmux::TmuxText::from(shell)),
                "{shell}"
            );
        }
        for program in ["", "cat", "fish", "nu", "pwsh", "BASH"] {
            assert!(
                !known_posix_shell(&libtmux::TmuxText::from(program)),
                "{program}"
            );
        }
        assert!(!known_posix_shell(&libtmux::TmuxText::from_bytes([
            b'b', 0xff
        ])));
    }

    async fn configure_dead_transition(pane: &libtmux::Pane) {
        pane.set_option("remain-on-exit", "on")
            .await
            .expect("fixture retains a dead pane");
        pane.set_hook("pane-died", "wait-for -S mcp-final-pane-died")
            .await
            .expect("dead transition is observable");
    }

    async fn caller_peer_identity(
        pane: &libtmux::Pane,
        server: &libtmux::Server,
    ) -> crate::CallerIdentity {
        let peer = pane
            .split(libtmux::SplitOptions::new(libtmux::SplitDirection::Below))
            .await
            .expect("caller peer is created");
        let generation = server.generation().await.expect("server generation");
        let session = peer.session_id().to_string();
        let session = session
            .strip_prefix('$')
            .expect("tmux session ID has its canonical prefix");
        crate::CallerIdentity::from_values(
            Some(
                format!(
                    "{},{},{}",
                    server.socket_path().display(),
                    generation.pid(),
                    session
                )
                .into(),
            ),
            Some(peer.id().to_string().into()),
        )
        .expect("caller identity is complete")
    }

    async fn transition_then_preflight(
        transition: &str,
        pane: &mut libtmux::Pane,
        server: &libtmux::Server,
        tools: &TmuxTools,
        source: &str,
        foreground: &libtmux::TmuxText,
        lease: &run_request::PaneReservation,
    ) -> Result<(), ToolError> {
        if transition == "caller" {
            server
                .window_by_id(pane.window_id())
                .await
                .expect("window lookup")
                .expect("source window exists")
                .set_option("synchronize-panes", "on")
                .await
                .expect("caller peer enters the configured cohort");
        } else {
            let command = if transition == "dead" {
                "exit 0"
            } else {
                "exec sleep 30"
            };
            let pane_id = pane.id().clone();
            pane.respawn(Some(command), libtmux::Respawn::Replacing)
                .await
                .expect("pane begins its final transition");
            if transition == "dead" {
                assert_eq!(
                    server
                        .wait_for_channel("mcp-final-pane-died", Duration::from_secs(2))
                        .await
                        .expect("pane-died notification answers"),
                    libtmux::ChannelWait::Signalled
                );
            } else {
                libtmux::test::retry_until(Duration::from_secs(2), async || {
                    server
                        .pane_by_id(&pane_id)
                        .await
                        .ok()
                        .flatten()
                        .is_some_and(|pane| {
                            pane.current_command()
                                .is_some_and(|value| value.as_str() == Ok("sleep"))
                        })
                })
                .await
                .expect("selected socket reports the foreground transition");
            }
        }
        let final_plan = tools
            .preflight_reserved_pane_input(
                source,
                PaneInputReach::Synchronized,
                MissingSource::ObservedTransition,
                lease,
            )
            .await?;
        if transition == "foreground" && final_plan.target.current_command() != Some(foreground) {
            return Err(bad_input(format!(
                "pane {source} changed foreground command between run checkpoints"
            )));
        }
        Ok(())
    }

    #[test]
    fn an_uncertain_start_names_safe_recovery_without_an_unreachable_handle() {
        let source = libtmux::Server::builder()
            .socket_name("conflicting")
            .socket_path("/tmp/libtmux-rs-test/conflicting.sock")
            .build()
            .expect_err("two socket selectors are refused");
        let error =
            run_error(run_request::RunError::DispatchUnknown(Box::new(source))).into_error_data();
        let data = error.data.as_ref().expect("the failure carries metadata");

        assert_eq!(error.code, rmcp::model::ErrorCode::INTERNAL_ERROR);
        assert_eq!(data["kind"], "dispatch_unknown");
        assert_eq!(data["retryable"], false);
        assert_eq!(data["stale"], false);
        assert!(data.get("job").is_none());
        assert!(!error.message.contains("job-7"));
        assert!(error.message.contains("inspect the pane"));
        assert!(error.message.contains("Do not retry automatically"));
        assert!(error.message.contains("send_keys"));
    }

    #[tokio::test]
    #[allow(
        clippy::too_many_lines,
        reason = "one watcher must span each guarded final transition"
    )]
    async fn real_tmux_compat_final_preflight_observes_transition_before_dispatch() {
        for (transition, expected_refusal, expected_kind) in [
            ("dead", "is dead", "invalid_input"),
            ("foreground", "changed foreground command", "invalid_input"),
            ("caller", "refusing to send input", "self_protection"),
        ] {
            let guard = TestServer::builder().start().await.expect("tmux starts");
            let Some(guard) = crate::test_support::control_fixture(guard).await else {
                return;
            };
            let server = guard.server();
            let session = server
                .new_session(format!("run-final-{transition}"))
                .await
                .expect("session starts");
            let pane = session.panes().await.expect("panes list").remove(0);
            if transition == "dead" {
                configure_dead_transition(&pane).await;
            }
            let caller = if transition == "caller" {
                Some(caller_peer_identity(&pane, server).await)
            } else {
                None
            };
            let tools = TmuxTools::builder(server.clone()).caller(caller).build();
            let source = pane.id().to_string();
            let initial = tools
                .preflight_pane_input(
                    &source,
                    PaneInputReach::Synchronized,
                    MissingSource::CallerInput,
                )
                .await
                .expect("initial preflight accepts the live pane");
            let foreground = initial
                .target
                .current_command()
                .cloned()
                .expect("initial pane reports its foreground command");
            let executable = server
                .resolved_tmux_executable()
                .expect("fixture tmux resolves");
            let socket = initial.endpoint.clone();
            let lease = initial.reserve().expect("the fixture pane is unreserved");
            let final_lease = lease.clone();
            let baseline_clients = client_count(server).await;
            let mut transition_pane = pane.clone();
            let final_check = async {
                assert_eq!(
                    client_count(server).await,
                    baseline_clients + 1,
                    "{transition}: watcher is attached before the final checkpoint"
                );
                transition_then_preflight(
                    transition,
                    &mut transition_pane,
                    server,
                    &tools,
                    &source,
                    &foreground,
                    &final_lease,
                )
                .await
            };
            let cancelled = CancellationToken::new();

            let result = run_request::run(
                &initial.target,
                "printf should-not-run",
                Duration::from_secs(2),
                false,
                &cancelled,
                run_request::RunTransport {
                    server,
                    generation: initial.generation,
                    executable: executable.as_os_str(),
                    endpoint: &socket,
                    shell: foreground.as_bytes(),
                    lease,
                    echoes: tools.echoes.as_ref(),
                },
                final_check,
            )
            .await;

            let Err(run_request::RunError::Guard(error)) = result else {
                panic!("the final preflight must reject the {transition} transition");
            };
            let error = error.into_error_data();
            assert_eq!(error.code, rmcp::model::ErrorCode::INVALID_PARAMS);
            assert!(error.message.contains(expected_refusal), "{transition}");
            assert_eq!(
                error.data.expect("final refusal is classified")["kind"],
                expected_kind,
                "{transition}"
            );
            let screen = pane.capture().await.expect("refused pane remains readable");
            assert!(
                screen.iter().all(|line| !line
                    .as_bytes()
                    .windows(b"should-not-run".len())
                    .any(|part| part == b"should-not-run")),
                "{transition}: no command payload reached the pane"
            );
            assert_eq!(
                client_count(server).await,
                baseline_clients,
                "{transition}: final refusal closes the output watcher"
            );
            guard.shutdown().await.expect("tmux fixture shuts down");
        }
    }

    #[test]
    fn unavailable_cursor_identity_is_an_internal_failure() {
        let error = tail_error(TailError::OwnerUnavailable).into_error_data();
        let data = error.data.expect("the failure is classified");

        assert_eq!(error.code, rmcp::model::ErrorCode::INTERNAL_ERROR);
        assert_eq!(error.message, "capture cursor identity is unavailable");
        assert_eq!(data["kind"], "unreachable");
        assert_eq!(data["retryable"], true);
        assert_eq!(data["stale"], false);
        assert_eq!(data.as_object().map(serde_json::Map::len), Some(3));
    }

    #[test]
    fn a_busy_tail_opener_is_retryable_without_a_partial_effect() {
        let error = tail_error(TailError::OpeningAtCapacity { limit: 1 }).into_error_data();
        let data = error.data.expect("the failure is classified");

        assert_eq!(error.code, rmcp::model::ErrorCode::INTERNAL_ERROR);
        assert_eq!(data["kind"], "capacity");
        assert_eq!(data["retryable"], true);
        assert_eq!(data["stale"], false);
        assert_eq!(data["resource"], "tail_opening");
        assert_eq!(data["capacity"], 1);
    }

    #[test]
    fn a_failed_baseline_after_opening_reports_a_partial_effect() {
        let configuration_error = || {
            libtmux::Server::builder()
                .socket_name("conflicting")
                .socket_path("/tmp/libtmux-rs-test/conflicting.sock")
                .build()
                .expect_err("two socket selectors are refused")
        };
        let existing = tail_error(TailError::Snapshot {
            error: configuration_error(),
            opened: false,
        })
        .into_error_data();
        let existing_data = existing.data.expect("the failure is classified");
        assert_eq!(existing_data["kind"], "unreachable");

        let error = tail_error(TailError::Snapshot {
            error: configuration_error(),
            opened: true,
        })
        .into_error_data();
        let data = error.data.expect("the failure is classified");

        assert_eq!(error.code, rmcp::model::ErrorCode::INTERNAL_ERROR);
        assert_eq!(data["kind"], "partial_effect");
        assert_eq!(data["retryable"], false);
        assert_eq!(data["stale"], false);
    }
}

crates/tmux-mcp/src/views.rs.content:
//! What the tools answer with.
//!
//! Every tool returns one of these rather than a string, so the shape it
//! promises is published as an output schema and the value arrives as
//! structured content. An agent reads fields instead of parsing prose, and the
//! doc comments here become the descriptions it reads while doing it.
//!
//! Lists are wrapped in a named object rather than returned bare. The protocol
//! says structured content is an object, and a wrapper leaves somewhere to put
//! a count or a cursor later without changing a shape callers already read.

use serde::Serialize;

use crate::caller::Relation;
use crate::schema::ChannelWaitOutcomeSchema;

/// One session, as the protocol sees it.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct SessionView {
    /// The `$`-prefixed tmux identity.
    pub id: String,
    /// The session name, absent when tmux reported none.
    pub name: String,
    /// How many windows the session holds.
    pub windows: u32,
    /// Whether any client is attached.
    pub attached: bool,
}

/// One window, as the protocol sees it.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct WindowView {
    /// The `@`-prefixed tmux identity.
    pub id: String,
    /// The session this window was reached through.
    pub session_id: String,
    /// The window's index within that session.
    pub index: i32,
    /// The window name.
    pub name: String,
    /// How many panes the window holds.
    pub panes: u32,
    /// Whether this is the session's active window.
    pub active: bool,
    /// Whether more than one session links this window.
    pub linked: bool,
}

/// One pane, as the protocol sees it.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct PaneView {
    /// The `%`-prefixed tmux identity.
    pub id: String,
    /// The window that contains the pane.
    pub window_id: String,
    /// The command currently running.
    pub command: Option<String>,
    /// The pane's working directory.
    pub path: Option<String>,
    /// Whether this is the window's active pane.
    pub active: bool,
    /// Whether this is the pane the MCP server itself runs in.
    ///
    /// `self` only on a confirmed match of both socket and pane id; `other`
    /// for every pane that is not, including one this crate cannot prove
    /// either way; `unknown` when the server is not running inside tmux, so
    /// the question has no answer.
    pub caller: Relation,
}

/// Every session on the server.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct Sessions {
    /// The sessions, in tmux's own order.
    pub sessions: Vec<SessionView>,
}

/// Every window asked for.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct Windows {
    /// The windows, in tmux's own order.
    pub windows: Vec<WindowView>,
}

/// Every pane asked for.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct Panes {
    /// The panes, in tmux's own order.
    pub panes: Vec<PaneView>,
}

/// One pane inside a described window.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct BranchPane {
    /// The `%`-prefixed tmux identity.
    pub id: String,
    /// The command currently running.
    pub command: Option<String>,
    /// Whether this is the window's active pane.
    pub active: bool,
}

/// One window inside a described session.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct BranchWindow {
    /// The `@`-prefixed tmux identity.
    pub id: String,
    /// The window's index within its session.
    pub index: i32,
    /// The window name.
    pub name: String,
    /// Whether this is the session's active window.
    pub active: bool,
    /// Whether more than one session links this window.
    pub linked: bool,
    /// The panes it holds.
    pub panes: Vec<BranchPane>,
}

/// One session with everything under it.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct Branch {
    /// The `$`-prefixed tmux identity.
    pub id: String,
    /// The session name.
    pub name: String,
    /// Whether any client is attached.
    pub attached: bool,
    /// The windows it holds.
    pub windows: Vec<BranchWindow>,
}

/// The whole hierarchy, in one answer.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct Tree {
    /// Every session, with its windows and their panes.
    pub sessions: Vec<Branch>,
}

/// Whether tmux knew where the last command's output began.
///
/// Reported rather than inferred: an answer that fell back to the whole
/// screen looks exactly like a command that printed a great deal.
#[derive(Debug, Serialize, schemars::JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum Marks {
    /// The prompt marks were there, so the text is one command's output.
    Present,
    /// tmux has the marks but this pane has none, because its shell does not
    /// emit OSC 133. fish does; bash and zsh need shell integration. The
    /// visible screen came back instead -- not the history, which would
    /// answer a request for one command with everything the pane ever wrote.
    Absent,
    /// This tmux predates `capture-pane -F`, which arrived in 3.7. The
    /// visible screen came back instead.
    Unsupported,
    /// The caller did not ask for the last command, so nothing was looked up.
    NotAsked,
}

/// What a pane is showing.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct Capture {
    /// The pane that was read.
    pub pane: String,
    /// The text, with lines separated by newlines.
    pub text: String,
    /// How many lines that is.
    pub lines: usize,
    /// Whether the text is one command's output, and why it is not.
    pub marks: Marks,
}

/// A pane's contents and the state a capture leaves out.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct Snapshot {
    /// The pane itself.
    pub pane: PaneView,
    /// How wide it is, in columns.
    pub width: u32,
    /// How tall it is, in rows.
    pub height: u32,
    /// Where the cursor sits, counting from the left.
    pub cursor_x: Option<u32>,
    /// Where the cursor sits, counting from the top.
    pub cursor_y: Option<u32>,
    /// Whether the pane is in a mode, where keys navigate rather than type.
    pub in_mode: bool,
    /// Which mode, when it is in one.
    pub mode: Option<String>,
    /// How far it is scrolled back, when it is in copy mode.
    pub scroll_position: Option<i32>,
    /// Whether the process in it has ended.
    pub dead: bool,
    /// What the pane is showing.
    pub content: String,
    /// How many lines of it are reported.
    pub lines: usize,
    /// How many older lines were dropped to honour `max_lines`.
    pub dropped: usize,
}

/// One line of one pane that matched a search.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct MatchView {
    /// The pane the line was found in.
    pub pane: String,
    /// The window that pane belongs to.
    pub window_id: String,
    /// Which line of the capture matched, counting from the top.
    pub line: usize,
    /// The line itself.
    pub text: String,
}

/// Where a pattern was found.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct Matches {
    /// Every matching line, in the order the panes were read.
    pub matches: Vec<MatchView>,
    /// How many panes were read to answer this.
    pub panes_searched: usize,
    /// Whether the match ceiling was reached, so there may be more.
    pub capped: bool,
}

/// What a pane wrote since a cursor.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct Since {
    /// The pane that was read.
    pub pane: String,
    /// The text, with escape sequences removed.
    ///
    /// After the first answer this is the raw output stream, not the rendered
    /// screen: a line redrawn in place repeats. `capture_pane` shows the
    /// screen.
    pub text: String,
    /// The cursor to pass back next time.
    pub cursor: String,
    /// Whether output between the previous cursor and this text was lost.
    pub missed: bool,
    /// Whether the pane has stopped writing for good.
    pub closed: bool,
    /// Whether this is the first answer, which reports the visible screen
    /// rather than what is new.
    pub first: bool,
}

/// The value of one tmux option.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct OptionValue {
    /// The option name.
    pub name: String,
    /// Its value, absent when it has never been set at that scope.
    pub value: Option<String>,
}

/// How a wait on a channel finished.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct ChannelWait {
    /// The channel that was waited on.
    pub channel: String,
    /// `signalled` or `deadline`.
    #[schemars(with = "ChannelWaitOutcomeSchema")]
    pub outcome: String,
}

/// A channel that was signalled.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct ChannelSignal {
    /// The channel that was signalled.
    pub channel: String,
}

/// Keys that were sent.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct Sent {
    /// The pane the caller targeted.
    pub pane: String,
    /// The effective configured recipient IDs observed before dispatch.
    ///
    /// Membership does not confirm delivery and may change after observation.
    pub panes: Vec<String>,
}

/// A pane's size after being resized.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct Size {
    /// The pane that was resized.
    pub pane: String,
    /// How wide it is now, in columns.
    pub width: u32,
    /// How tall it is now, in rows.
    pub height: u32,
}

/// An object that was destroyed.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct Killed {
    /// The id of what was destroyed.
    pub id: String,
}

/// What tmux holds under one environment name.
#[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize, schemars::JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum EnvironmentState {
    /// tmux holds a value and hands it to processes it starts.
    Set,
    /// tmux removes the name from the environment of processes it starts.
    Removed,
}

/// One tmux environment entry.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct EnvironmentEntry {
    /// The variable name.
    pub name: String,
    /// Whether the name holds a value or is marked for removal.
    pub state: EnvironmentState,
    /// The value, only for a set variable whose name the operator allowed in
    /// `LIBTMUX_ENVIRONMENT_VALUES` at startup.
    pub value: Option<String>,
    /// True for a set variable whose value was not returned because the
    /// operator did not allow its name.
    pub withheld: bool,
}

/// A tmux environment, server-wide or for one session.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct Environment {
    /// The entries, in tmux's own order.
    pub entries: Vec<EnvironmentEntry>,
    /// The session the environment belongs to, or absent for the server's.
    pub session: Option<String>,
}

/// One tmux hook.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct Hook {
    /// The hook name, such as `pane-exited`.
    pub name: String,
    /// Its index, when the hook is an array.
    pub index: Option<u32>,
    /// The command tmux runs.
    pub command: String,
}

/// The hooks set at one scope.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct Hooks {
    /// The hooks, in tmux's own order.
    pub hooks: Vec<Hook>,
}

/// A window whose layout was set.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct Layout {
    /// The window that was arranged.
    pub window: String,
    /// The layout it now has, in tmux's own syntax.
    pub layout: String,
}

/// A pane that was cleared, respawned, or retitled.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct PaneChanged {
    /// The pane that changed.
    pub pane: String,
}

/// Text that was pasted into a pane.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct Pasted {
    /// The pane it went into.
    pub pane: String,
    /// How many bytes came from `text`, excluding optional Enter.
    pub bytes: usize,
}

